window.HB_TR["john"]["ur"]=["1۔ ابتدا میں کلام تھا، اور کلام خدا کے ساتھ تھا، اور کلام خدا تھا۔\n2. شروع میں خدا کے ساتھ بھی یہی تھا۔\n3۔ تمام چیزیں اس نے بنائی تھیں؛ اور اس کے بغیر کوئی بھی چیز بنتی ہی نہیں تھی۔\n4۔ اس میں زندگی تھی؛ اور زندگی انسانوں کی روشنی تھی۔\n5۔ اور روشنی اندھیرے میں چمکتی ہے؛ اور اندھیرا اسے نہیں سمجھتا۔ {سمجھا گیا: یا، قبول نہیں کیا، یا، قبول نہیں کیا}\n6۔ خدا کی طرف سے بھیجا گیا ایک آدمی تھا، جس کا نام {یوحنا} تھا۔\n7۔ یہی بات گواہی دینے کے لیے بھی ہوئی، روشنی کی گواہی دینے کے لیے، تاکہ اس کے ذریعے تمام لوگ ایمان لائیں۔\n8. وہ وہ روشنی نہیں تھا، بلکہ {بھیجا گیا} تاکہ اس روشنی کی گواہی دے۔\n9۔ {یہ} سچی روشنی تھی، جو ہر انسان کو روشن کرتی ہے جو دنیا میں آتا ہے۔\n10. وہ دنیا میں تھا، اور دنیا اس نے بنائی تھی، اور دنیا اسے نہیں جانتی تھی۔\n11۔ وہ اپنے پاس آیا، اور اس کے لوگوں نے اسے قبول نہیں کیا۔\n12. لیکن جتنے لوگوں نے اسے قبول کیا، انہوں نے انہیں خدا کے بیٹے بننے کی طاقت دی، {حتیٰ کہ} ان لوگوں کو بھی جو اس کے نام پر ایمان لاتے ہیں: {طاقت: یا، حق، یا، مراعات}\n13۔ جو خون سے پیدا نہیں ہوئے، نہ جسم کی مرضی سے، نہ انسان کی مرضی سے، بلکہ خدا سے۔\n14۔ اور کلام جسم میں بن گیا، اور ہمارے درمیان رہا، (اور ہم نے اس کی شان دیکھی، جو باپ کے واحد بیٹے کی شان ہے)، جو فضل اور سچائی سے بھرپور تھا۔\n15۔ یوحنا نے اس کی گواہی دی اور پکارا، کہا، یہ وہی ہے جس کے بارے میں میں نے بات کی تھی، جو میرے بعد آتا ہے وہ مجھ سے پہلے آتا ہے: کیونکہ وہ میرے پہلے تھا۔\n16۔ اور اس کی کمال کی جو کچھ ہمیں ملی، اور فضل کے بدلے فضل حاصل کریں۔\n17۔ کیونکہ شریعت موسیٰ نے دی تھی، {لیکن} فضل اور سچائی یسوع مسیح کی طرف سے آئی۔\n18۔ کسی انسان نے کبھی خدا کو نہیں دیکھا؛ اکلوتا بیٹا، جو باپ کے گود میں ہے، اس نے {وہ} قرار دیا ہے۔\n19۔ اور یہ یوحنا کا ریکارڈ ہے، جب یہودیوں نے یروشلم سے پادریوں اور لاویوں کو بھیجا کہ وہ اس سے پوچھیں، تم کون ہو؟\n20۔ اور اس نے اعتراف کیا، اور انکار نہیں کیا؛ لیکن اعتراف کیا، میں مسیح نہیں ہوں۔\n21۔ اور انہوں نے اس سے پوچھا، پھر کیا؟ کیا تم ایلیاس ہو؟ اور وہ کہتا ہے، میں نہیں ہوں۔ کیا تم وہ نبی ہو؟ اور اس نے جواب دیا، نہیں۔ {وہ نبی: یا، ایک نبی؟}\n22۔ پھر انہوں نے اس سے کہا، تم کون ہو؟ تاکہ ہم ان لوگوں کو جواب دے سکیں جنہوں نے ہمیں بھیجا۔ تم اپنے بارے میں کیا کہتے ہو؟\n23۔ اس نے کہا، میں ویرانے میں پکار رہے شخص کی آواز ہوں، خداوند کا راستہ سیدھا کرو، جیسا کہ نبی یسعیا نے فرمایا۔\n24۔ اور جو بھیجے گئے وہ فریسیوں کے تھے۔\n25۔ اور انہوں نے اس سے پوچھا اور کہا، تو پھر تم کیوں بپتسمہ لیتے ہو، اگر تم وہ مسیح نہیں ہو، نہ ایلیاس، نہ وہ نبی؟\n26۔ یوحنا نے ان کا جواب دیا، کہا، میں پانی سے بپتسمہ دیتا ہوں: لیکن تم میں سے ایک کھڑا ہے جسے تم نہیں جانتے؛\n27. وہی ہے، جو میرے بعد آتا ہے، مجھ سے پہلے ترجیح دی جاتی ہے، جس کے جوتے کی کنڈی میں کھولنے کے قابل نہیں ہوں۔\n28۔ یہ کام اردن کے پار بیت بارہ میں کیے جاتے تھے، جہاں یوحنا بپتسمہ لے رہا تھا۔\n29۔ اگلے دن یوحنا دیکھتا ہے کہ یسوع اس کے پاس آ رہا ہے، اور کہتا ہے، دیکھو خدا کا برہ جو دنیا کے گناہ کو دور کرتا ہے۔ {لے جاتا ہے: یا، برداشت کرتا ہے}\n30۔ یہی وہ ہے جس کے بارے میں میں نے کہا تھا، میرے بعد ایک ایسا آدمی آتا ہے جو مجھ سے پہلے پسند کیا جاتا ہے: کیونکہ وہ میرے پہلے تھا۔\n31۔ اور میں اسے نہیں جانتا تھا: بس یہ کہ وہ اسرائیل کے سامنے ظاہر ہو جائے، اس لیے میں پانی سے بپتسمہ لینے آیا ہوں۔\n32۔ اور یوحنا نے بیان کیا، کہا، میں نے روح کو آسمان سے کبوتر کی طرح اترتے دیکھا، اور وہ اس پر ٹھہر گئی۔\n33۔ اور میں اسے نہیں جانتا، لیکن جس نے مجھے پانی سے بپتسمہ دینے بھیجا، وہی مجھ سے کہا، جس پر تم روح کو اترتے اور اس پر رہتے ہوئے دیکھو گے، وہی ہے جو روح القدس سے بپتسمہ لیتا ہے۔\n34۔ اور میں نے دیکھا، اور صاف ظاہر کیا کہ یہ خدا کا بیٹا ہے۔\n35۔ اگلے دن پھر یوحنا اور اس کے دو شاگرد کھڑے ہوئے؛\n36۔ اور یسوع کو دیکھتے ہوئے جب وہ چل رہا تھا، وہ کہتا ہے، دیکھو خدا کا برہ!\n37۔ اور دونوں شاگردوں نے اسے بولتے سنا، اور وہ یسوع کے پیچھے چل پڑے۔\n38۔ پھر یسوع نے پلٹ کر انہیں پیچھے آتے دیکھا، اور ان سے کہا، تم کیا چاہتے ہو؟ انہوں نے اس سے کہا، ربی، (یعنی، تشریح کے باعث، ماسٹر،) کہ تم کہاں رہتے ہو؟ {رہائشی: یا، ہمیشہ کے لیے}\n39۔ وہ ان سے کہتا ہے، آؤ اور دیکھو۔ وہ آئے اور دیکھا کہ وہ کہاں رہتا ہے، اور اس دن اس کے ساتھ رہے: کیونکہ تقریبا دسویں وقت تھا۔ {تقریبا...: یہ رات سے دو گھنٹے پہلے تھا}\n40۔ ان دو میں سے ایک جنہوں نے جان کو {بولتے سنا} اور اس کے پیچھے چلے، وہ اینڈریو تھا، جو سائمن پیٹر کا بھائی تھا۔\n41۔ وہ سب سے پہلے اپنے بھائی شمعون کو پاتا ہے، اور اسے کہتا ہے، ہم نے مسیحا کو پایا ہے، جو کہ تشریح کے مطابق مسیح ہے۔ {مسیح: یا، مسح شدہ}\n42۔ اور وہ اسے یسوع کے پاس لے آیا۔ اور جب یسوع نے اسے دیکھا تو کہا، تو تو شمعون یونا کا بیٹا ہے: تمہیں کیفاس کہا جائے گا، جو تشریح کے مطابق ایک پتھر ہے۔\n43۔ اگلے دن یسوع گلیل میں جائیں گے، فلپ کو پائیں گے، اور اس سے کہیں گے، میرے پیچھے آؤ۔\n44۔ اب فلپ بیت صیدا کا تھا، جو اندریو اور پیٹر کا شہر تھا۔\n45۔ فلپ نتھنائیل کو پاتا ہے اور اسے کہتا ہے، ہم نے اسے پایا ہے، جس کے بارے میں موسیٰ نے شریعت میں اور نبیوں نے لکھا تھا، یسوع ناصرت، یوسف کا بیٹا۔\n46۔ اور نتھنائیل نے اس سے کہا، کیا ناصرت سے کوئی اچھی چیز نکل سکتی ہے؟ فلپ اسے کہتا ہے، آؤ اور دیکھو۔\n47۔ یسوع نے نتھنائیل کو اپنے پاس آتے دیکھا، اور اس کے بارے میں کہا، دیکھو واقعی ایک اسرائیلی جس میں کوئی چال نہیں!\n48۔ نتھنائیل نے اسے کہا، تم مجھے کہاں سے جانتے ہو؟ یسوع نے جواب دیا اور اسے کہا، اس سے پہلے کہ فلپ نے تمہیں بلایا، جب تم انجیر کے درخت کے نیچے تھے، میں نے تمہیں دیکھا۔\n49۔ نتھنائیل نے جواب دیا اور اسے کہا، ربی، تو خدا کا بیٹا ہے؛ تم اسرائیل کے بادشاہ ہو۔\n50۔ یسوع نے جواب دیا اور کہا، کیونکہ میں نے تم سے کہا، میں نے تمہیں انجیر کے درخت کے نیچے دیکھا، کیا تم یقین کرتے ہو؟ تم ان سے بڑی چیزیں دیکھو گے۔\n51۔ اور وہ اس سے کہتا ہے، واقعی، یقینا، میں تم سے کہتا ہوں، آخرت میں تم آسمان کو کھلتے دیکھو گے، اور خدا کے فرشتے انسان کے بیٹے پر چڑھیں گے اور اتریں گے۔","1۔ اور تیسرے دن گلیل کے قانا میں شادی ہوئی؛ اور یسوع کی ماں وہاں تھی:\n2۔ اور یسوع اور اس کے شاگردوں دونوں کو شادی کے لیے بلایا گیا۔\n3۔ اور جب انہوں نے شراب چاہی، تو یسوع کی ماں نے اسے کہا، ان کے پاس شراب نہیں ہے۔\n4۔ یسوع نے اس سے کہا، اے عورت، میرا تم سے کیا تعلق ہے؟ میرا وقت ابھی نہیں آیا۔\n5۔ اس کی ماں خادموں سے کہتی ہے، جو بھی وہ تم سے کہے، وہ کرو۔\n6۔ اور وہاں چھ پتھروں کے برتن رکھے گئے، جو یہودیوں کی تطہیر کے طریقے کے مطابق تھے، جن میں ہر ایک میں دو یا تین فرکن تھے۔\n7۔ یسوع نے ان سے کہا، پانی کے برتنوں کو پانی سے بھر دو۔ اور انہوں نے انہیں مکمل طور پر بھر دیا۔\n8۔ اور وہ ان سے کہتا ہے، اب نکل جاؤ اور دعوت کے گورنر کے پاس جاؤ۔ اور وہ اسے ظاہر کرتے ہیں۔\n9۔ جب دعوت کے حکمران نے شراب بننے والے پانی کا ذائقہ چکھا اور نہ جانے کہ یہ کہاں سے ہے: (لیکن پانی نکالنے والے خادم جانتے تھے؛) دعوت کے گورنر نے دولہا کو بلایا،\n10۔ اور اسے کہتا ہے، ہر انسان ابتدا میں اچھی شراب بناتا ہے؛ اور جب لوگ اچھی طرح پی لیں، تو جو برا ہے: {لیکن} تم نے اب تک اچھی شراب رکھی ہے۔\n11۔ معجزات کی یہ شروعات یسوع نے قانا آف گلیل میں کی، اور اس کی شان کو ظاہر کیا؛ اور اس کے شاگردوں نے اس پر یقین کیا۔\n12۔ اس کے بعد وہ کفرناحوم گیا، وہ، اپنی ماں، اس کے بھائی اور شاگرد، اور وہ وہاں زیادہ دن نہیں رہے۔\n13۔ اور یہودیوں کا فسح قریب آ گیا، اور یسوع یروشلم چلے گئے،\n14۔ اور مندر میں وہ لوگ ملے جو بیل، بھیڑ، کبوتر بیچتے تھے، اور پیسے کے بدلے والے بیٹھے تھے:\n15۔ اور جب اس نے چھوٹے رسیوں کا ایک کوڑا بنایا، تو اس نے سب کو مندر سے نکال دیا، بھیڑوں اور بیلوں کو؛ اور چینجرز کے پیسے نکال دیے، اور میزیں گرا دیں؛\n16۔ اور انہوں نے کبوتر بیچنے والوں سے کہا، یہ چیزیں یہاں سے لے جاؤ؛ میرے والد کے گھر کو سامان کا گھر نہ بناؤ۔\n17۔ اور اس کے شاگردوں کو یاد آیا کہ یہ لکھا تھا، تمہارے گھر کے جذبے نے مجھے کھا لیا ہے۔\n18۔ پھر یہودیوں نے جواب دیا اور اس سے کہا، تم نے ہمیں کیا نشان دکھایا، جب تم یہ سب کرتے ہو؟\n19۔ یسوع نے جواب دیا اور ان سے کہا، اس مندر کو تباہ کرو، اور تین دن میں اسے دوبارہ زندہ کروں گا۔\n20۔ پھر یہودیوں نے کہا، یہ مندر چھیالیس سال سے تعمیر ہو رہا ہے، اور کیا تم اسے تین دن میں دوبارہ تعمیر کرو گے؟\n21۔ لیکن اس نے اپنے جسم کے مندر کی بات کی۔\n22۔ جب وہ مردوں میں سے زندہ ہوا، تو اس کے شاگردوں کو یاد آیا کہ اس نے یہ بات ان سے کہی تھی؛ اور انہوں نے صحیفہ اور یسوع کے کلام پر ایمان لایا۔\n23۔ اب جب وہ یروشلم میں فسح کے موقع پر، تہوار {دن} میں تھا، تو بہت سے لوگوں نے اس کے نام پر ایمان لایا، جب انہوں نے وہ معجزات دیکھے جو انہوں نے دیکھے۔\n24۔ لیکن یسوع نے خود کو ان کے سپرد نہیں کیا، کیونکہ وہ تمام {انسان} کو جانتا تھا،\n25۔ اور اس کی ضرورت نہیں تھی کہ کوئی انسان کے بارے میں گواہی دے: کیونکہ وہ جانتا تھا کہ انسان میں کیا ہے۔","1۔ فریسیوں میں سے ایک شخص تھا، جس کا نام نیکودیموس تھا، جو یہودیوں کا حکمران تھا:\n2۔ وہی رات کو یسوع کے پاس آیا اور اسے کہا، ربی، ہم جانتے ہیں کہ تم خدا کی طرف سے استاد ہو، کیونکہ کوئی انسان یہ معجزات نہیں کر سکتا جو تم کرتے ہو، سوائے اس کے کہ خدا اس کے ساتھ ہو۔\n3۔ یسوع نے جواب دیا اور کہا، \"یقینا، یقینا، میں تم سے کہتا ہوں، جب تک انسان دوبارہ پیدا نہ ہو، وہ خدا کی بادشاہی کو نہیں دیکھ سکتا۔ {دوبارہ: یا، اوپر سے}\n4۔ نیکودیمس اس سے کہتا ہے، ایک انسان بوڑھا ہو کر کیسے پیدا ہو سکتا ہے؟ کیا وہ دوسری بار اپنی ماں کے رحم میں داخل ہو سکتا ہے، اور پیدا ہو سکتا ہے؟\n5۔ یسوع نے جواب دیا، واقعی، واقعی، میں تم سے کہتا ہوں، جب تک انسان پانی اور روح سے پیدا نہ ہو، وہ خدا کی بادشاہی میں داخل نہیں ہو سکتا۔\n6۔ جو جسم سے پیدا ہوتا ہے وہ گوشت ہے؛ اور جو روح سے پیدا ہوتا ہے وہ روح ہے۔\n7۔ حیران نہ ہو کہ میں نے تم سے کہا، تمہیں دوبارہ جنم لینا ہوگا۔ {دوبارہ: یا، اوپر سے}\n8۔ ہوا جہاں چاہے چلتی ہے، اور تم اس کی آواز سنتے ہو، لیکن یہ نہیں بتا سکتے کہ یہ کہاں سے آتی ہے اور کہاں جاتی ہے: اسی طرح ہر وہ شخص جو روح سے پیدا ہوا ہے۔\n9۔ نیکودیمس نے جواب دیا اور اس سے کہا، یہ سب کیسے ہو سکتا ہے؟\n10۔ یسوع نے جواب دیا اور اس سے کہا، کیا تم اسرائیل کے مالک ہو، اور ان باتوں کو نہیں جانتے؟\n11۔ واقعی، یقینا، میں تم سے کہتا ہوں، ہم کہتے ہیں کہ ہم جانتے ہیں، اور گواہی دیتے ہیں کہ ہم نے دیکھا ہے؛ اور تم ہماری گواہی قبول نہیں کرتے۔\n12۔ اگر میں نے تمہیں دنیاوی باتیں بتائی ہیں اور تم یقین نہیں کرتے، تو تم کیسے یقین کرو گے اگر میں تمہیں آسمانی باتیں بتاؤں؟\n13۔ اور کوئی انسان آسمان پر نہیں چڑھا، سوائے اس کے جو آسمان سے اترتا ہے، {حتیٰ کہ} انسان کا بیٹا جو آسمان میں ہے۔\n14۔ اور جیسے موسیٰ نے صحرا میں سانپ کو اٹھایا، ویسے ہی انسان کے بیٹے کو بھی اٹھایا جانا چاہیے:\n15۔ جو اس پر ایمان لاتا ہے وہ فنا نہ ہو بلکہ ہمیشہ کی زندگی پائے۔\n16۔ کیونکہ خدا نے دنیا سے اتنی محبت کی کہ اس نے اپنا اکلوتا بیٹا دے دیا، تاکہ جو اس پر ایمان لائے وہ فنا نہ ہو بلکہ ہمیشہ کی زندگی حاصل کرے۔\n17۔ کیونکہ خدا نے اپنے بیٹے کو دنیا میں بھیجا تاکہ دنیا کو سزا دے؛ لیکن اس کے ذریعے دنیا کو بچایا جا سکتا ہے۔\n18۔ جو اس پر ایمان لاتا ہے وہ ملامت نہیں ہوتا؛ لیکن جو ایمان نہیں لاتا، وہ پہلے ہی ملامت شدہ ہے، کیونکہ اس نے خدا کے واحد بیٹے کے نام پر ایمان نہیں لایا۔\n19۔ اور یہ مذمت ہے، کہ روشنی دنیا میں آئی ہے، اور انسانوں نے روشنی کے بجائے تاریکی کو پسند کیا، کیونکہ ان کے اعمال برے تھے۔\n20۔ کیونکہ جو کوئی برا کرتا ہے وہ روشنی سے نفرت کرتا ہے، نہ روشنی میں آتا ہے، ورنہ اس کے اعمال ملامت کیے جائیں گے۔ {ملامت شدہ: یا، دریافت شدہ}\n21. لیکن جو سچائی کرتا ہے وہ روشنی میں آتا ہے، تاکہ اس کے اعمال ظاہر ہوں، تاکہ وہ خدا میں ہوں۔\n22۔ ان سب کے بعد یسوع اور اس کے شاگرد یہودیہ کی سرزمین میں آئے؛ اور وہاں وہ ان کے ساتھ رکا اور بپتسمہ لیا۔\n23۔ اور یوحنا بھی سلیم کے قریب عینون میں بپتسمہ دے رہا تھا، کیونکہ وہاں بہت پانی تھا: اور وہ آئے اور بپتسمہ لیا۔\n24۔ کیونکہ جان کو ابھی قید میں نہیں ڈالا گیا تھا۔\n25۔ پھر یوحنا کے کچھ شاگردوں اور یہودیوں کے درمیان پاکیزگی کے بارے میں سوال پیدا ہوا۔\n26۔ اور وہ یوحنا کے پاس آئے، اور اسے کہا، اے ربی، جو تیرے ساتھ اردن کے پار ہے، جس کی گواہی ہے، دیکھو، وہی بپتسمہ دیتا ہے، اور تمام لوگ اس کے پاس آتے ہیں۔\n27۔ یوحنا نے جواب دیا اور کہا، انسان کچھ حاصل نہیں کر سکتا جب تک کہ اسے آسمان سے نہ دیا جائے۔ {وصول کرنا: یا، اپنے پاس لے جانا}\n28۔ تم خود گواہی دو کہ میں نے کہا، میں مسیح نہیں ہوں، بلکہ میں اس کے سامنے بھیجا گیا ہوں۔\n29۔ جس کے پاس دلہن ہے وہ دولہا ہے: لیکن دولہا کا دوست، جو کھڑا ہے اور اسے سنتا ہے، دولہے کی آواز کی وجہ سے بہت خوش ہوتا ہے: لہٰذا یہ میری خوشی پوری ہوتی ہے۔\n30۔ اسے بڑھانا ہوگا، لیکن مجھے کم کرنا ہوگا۔\n31۔ جو اوپر سے آتا ہے وہ سب سے بلند ہے: جو زمین سے ہے وہ زمینی ہے، اور زمین کی بات کرتا ہے؛ جو آسمان سے آتا ہے وہ سب سے بلند ہے۔\n32۔ اور جو کچھ اس نے دیکھا اور سنا، وہ گواہی دیتا ہے؛ اور کوئی شخص اس کی گواہی نہیں لیتا۔\n33۔ جس نے اس کی گواہی حاصل کی ہے، اس نے اپنی مہر پر لگا دی ہے کہ خدا سچا ہے۔\n34۔ کیونکہ جو خدا نے بھیجا ہے وہ خدا کے الفاظ بولتا ہے: کیونکہ خدا روح کو پیمائش سے نہیں دیتا۔\n35۔ باپ بیٹے سے محبت کرتا ہے، اور سب کچھ اس کے ہاتھ میں دے دیا ہے۔\n36۔ جو بیٹے پر ایمان رکھتا ہے اسے دائمی زندگی ملتی ہے: اور جو بیٹے پر ایمان نہیں رکھتا وہ زندگی نہیں دیکھے گا؛ لیکن خدا کا غضب اس پر قائم ہے۔","1۔ جب خداوند جانتا تھا کہ فریسیوں نے سنا کہ یسوع نے یوحنا سے زیادہ شاگرد بنائے اور بپتسمہ دیے،\n2۔ (اگرچہ یسوع نے خود بپتسمہ نہیں دیا بلکہ اس کے شاگردوں کو بپتسمہ دیا،)\n3۔ وہ یہودیہ چھوڑ کر دوبارہ گلیل چلا گیا۔\n4۔ اور اسے سامریہ سے گزرنا ہوگا۔\n5۔ پھر وہ سامریہ کے ایک شہر پہنچتا ہے، جسے سیخار کہا جاتا ہے، جو اس زمین کے ٹکڑے کے قریب ہے جو یعقوب نے اپنے بیٹے یوسف کو دیا تھا۔\n6۔ اب جیکب کا کنواں وہاں تھا۔ یسوع، جو اپنے سفر سے تھک چکے تھے، کنویں پر یوں بیٹھ گئے: {اور} تقریبا چھٹے گھنٹے کا وقت تھا۔\n7۔ سامریہ کی ایک عورت آتی ہے پانی پینے کے لیے: یسوع اس سے کہتا ہے، مجھے پانی دو۔\n8۔ (کیونکہ اس کے شاگرد گوشت خریدنے شہر چلے گئے تھے۔)\n9۔ پھر سامریہ کی عورت اس سے کہتی ہے، کیسے ہو سکتا ہے کہ تم، یہودی ہونے کے ناطے، مجھ سے مشروب مانگتے ہو، جو سامریہ کی عورت ہوں؟ کیونکہ یہودیوں کا سامریتیوں سے کوئی واسطہ نہیں۔\n10۔ یسوع نے جواب دیا اور اس سے کہا، اگر تم خدا کے تحفے کو جانتی ہو، اور جو تمہیں کہتا ہے، مجھے پینے دو؛ تم اس سے مانگتے، اور وہ تمہیں زندہ پانی دیتا۔\n11۔ عورت اس سے کہتی ہے، جناب، تمہارے پاس کھینچانے کو کچھ نہیں ہے، اور کنواں گہرا ہے: تو پھر وہ زندہ پانی کہاں سے آیا؟\n12۔ کیا تم ہمارے والد یعقوب سے عظیم ہو، جس نے ہمیں کنواں دیا، اور خود اس میں سے پی، اپنے بچوں اور مویشیوں کو؟\n13۔ یسوع نے جواب دیا اور اس سے کہا، جو بھی اس پانی سے پائے گا وہ پھر پیاس لگائے گا:\n14۔ لیکن جو بھی اس پانی سے پیتا ہے جو میں اسے دوں گا، وہ کبھی پیاس نہیں لگائے گا؛ لیکن جو پانی میں اسے دوں گا، وہ اس میں ایک ایسا پانی کا کنواں ہوگا جو ہمیشہ کی زندگی کی طرف پھوٹے گا۔\n15۔ عورت اس سے کہتی ہے، صاحب، مجھے یہ پانی دو، کہ مجھے پیاس نہیں لگی اور نہ ہی یہاں آ کر پانی پیتا ہوں۔\n16۔ یسوع نے اس سے کہا، جاؤ، اپنے شوہر کو بلاؤ، اور یہاں آ جاؤ۔\n17۔ عورت نے جواب دیا اور کہا، میرا کوئی شوہر نہیں ہے۔ یسوع نے اس سے کہا، تو نے اچھا کہا، میرا کوئی شوہر نہیں:\n18۔ کیونکہ تمہارے پانچ شوہر تھے؛ اور جو اب تمہارے پاس ہے وہ تمہارا شوہر نہیں ہے: اس میں تم نے سچ کہا۔\n19۔ عورت اس سے کہتی ہے، جناب، میں سمجھتی ہوں کہ تم نبی ہو۔\n20۔ ہمارے آباؤ اجداد اس پہاڑ میں عبادت کرتے تھے؛ اور تم کہتے ہو کہ یروشلم میں وہ جگہ ہے جہاں لوگوں کو عبادت کرنی چاہیے۔\n21۔ یسوع نے اس سے کہا، اے عورت، یقین کرو، وہ وقت آئے گا جب تم نہ اس پہاڑ میں، نہ ابھی یروشلم میں، باپ کی عبادت کرو گی۔\n22۔ تم عبادت کرتے ہو جو تم نہیں جانتے: ہم جانتے ہیں کہ ہم کس چیز کی عبادت کرتے ہیں: کیونکہ نجات یہودیوں کی ہے۔\n23۔ لیکن وہ وقت آ رہا ہے، اور اب ہے، جب سچے عبادت گزار روح اور سچائی میں باپ کی عبادت کریں گے: کیونکہ باپ ایسے لوگوں کی عبادت کی خواہش رکھتا ہے۔\n24. خدا {ہے} ایک روح: اور جو اس کی عبادت کرتے ہیں انہیں روح اور سچائی میں [اسے} عبادت کرنی چاہیے۔\n25۔ عورت اس سے کہتی ہے، میں جانتی ہوں کہ مسیحا آ رہا ہے، جسے مسیح کہا جاتا ہے: جب وہ آئے گا، وہ ہمیں سب کچھ بتائے گا۔\n26۔ یسوع اس سے کہتا ہے، میں جو تم سے بات کرتا ہوں {وہ}۔\n27۔ اور اس پر اس کے شاگرد آئے، اور حیران ہوئے کہ اس نے عورت سے بات کی، لیکن کسی نے نہیں کہا، تم کیا چاہتے ہو؟ یا، تم اس سے کیوں بات کرتے ہو؟\n28۔ عورت پھر اپنا پانی کا برتن چھوڑ کر شہر کی طرف چلی گئی، اور مردوں سے کہا،\n29۔ آؤ، ایک آدمی کو دیکھو، جس نے مجھے وہ سب کچھ بتایا جو میں نے کبھی کیا: کیا یہ مسیح نہیں ہے؟\n30۔ پھر وہ شہر سے باہر نکلے اور اس کے پاس آئے۔\n31۔ اسی دوران اس کے شاگردوں نے اس سے دعا کی اور کہا، استاد، کھاؤ۔\n32۔ لیکن اس نے ان سے کہا، میرے پاس کھانے کے لیے گوشت ہے جو تم نہیں جانتے۔\n33۔ لہٰذا شاگردوں نے ایک دوسرے سے کہا، کیا کسی نے اسے کھانے کے لیے لایا ہے؟\n34۔ یسوع ان سے فرماتا ہے، میرا گوشت ہے کہ میں اس کی مرضی پوری کروں جس نے مجھے بھیجا، اور اس کا کام مکمل کرے۔\n35۔ یہ نہ کہو، ابھی چار مہینے باقی ہیں، اور {پھر} فصل آئے گی؟ دیکھو، میں تم سے کہتا ہوں، اپنی آنکھیں اٹھاؤ اور کھیتوں کو دیکھو؛ کیونکہ وہ پہلے ہی سفید ہو چکے ہیں۔\n36۔ اور جو کاٹتا ہے، وہ اجرت لیتا ہے اور ابدی زندگی کے لیے پھل جمع کرتا ہے، تاکہ جو بیج پیدا کرتا ہے اور جو کاٹتا ہے، دونوں مل کر خوش رہیں۔\n37۔ اور یہاں وہ قول ہے، ایک بوتا ہے اور دوسرا کاٹتا ہے۔\n38۔ میں نے تمہیں بھیجا ہے کہ وہ کاٹو جو تم نے محنت نہیں کی: دوسرے لوگ محنت کرتے ہیں، اور تم ان کی محنت میں شامل ہو۔\n39۔ اور اس شہر کے بہت سے سامری اس پر اس عورت کے قول پر ایمان رکھتے تھے، جس نے گواہی دی، اس نے مجھے وہ سب کچھ بتایا جو میں نے کیا۔\n40۔ جب سامری اس کے پاس آئے تو انہوں نے اس سے درخواست کی کہ وہ ان کے ساتھ رہے: اور وہ وہاں دو دن رکا۔\n41۔ اور بہت سے لوگ اس کے اپنے کلام کی وجہ سے ایمان لاتے ہیں؛\n42۔ اور عورت سے کہا، اب ہم ایمان لاتے ہیں، تیری بات کی وجہ سے نہیں، کیونکہ ہم نے خود اس کی بات سنی ہے، اور جانتے ہیں کہ یہ واقعی مسیح ہے، دنیا کا نجات دہندہ۔\n43۔ اب دو دن بعد وہ وہاں سے روانہ ہوا اور گلیل چلا گیا۔\n44۔ کیونکہ خود یسوع نے گواہی دی کہ نبی کو اپنے ملک میں عزت حاصل نہیں ہوتی۔\n45۔ پھر جب وہ گلیل میں آیا، تو گلیلیائیوں نے اس کا استقبال کیا، کیونکہ انہوں نے یروشلم میں عید میں جو کچھ کیا وہ سب کچھ دیکھ چکا تھا، کیونکہ وہ بھی دعوت میں گئے تھے۔\n46۔ یوں یسوع دوبارہ گلیل کے قانا میں آیا، جہاں اس نے پانی کی شراب بنائی۔ اور ایک خاص اشرافیہ تھا، جس کا بیٹا کفرناحوم میں بیمار تھا۔ {نوبل مین: یا، درباری، یا، حکمران}\n47۔ جب اس نے سنا کہ یسوع یہودیہ سے گلیل میں آیا ہے، تو وہ اس کے پاس گیا اور اس سے التجا کی کہ وہ نیچے آئے اور اپنے بیٹے کو شفا دے، کیونکہ وہ موت کے قریب تھا۔\n48۔ پھر یسوع نے اس سے کہا، جب تک تم نشانیاں اور عجائبات نہیں دیکھو گے، تم یقین نہیں کرو گے۔\n49۔ اشرافیہ نے اس سے کہا، جناب، نیچے آ جاؤ اس سے پہلے کہ میرا بچہ مر جائے۔\n50۔ یسوع اسے کہتے ہیں، اپنا راستہ چلو؛ تمہارا بیٹا زندہ ہے۔ اور اس آدمی نے یسوع کے کہے ہوئے کلام پر ایمان لایا اور اپنی راہ پر چل پڑا۔\n51۔ اور جب وہ اب نیچے جا رہا تھا، اس کے خادموں نے اس سے ملاقات کی اور {اسے} سے کہا، کہ تیرے بیٹے زندہ ہیں۔\n52۔ پھر اس نے ان سے اس وقت پوچھا جب اس نے اصلاح شروع کی۔ اور انہوں نے اسے کہا، کل ساتویں گھنٹے پر بخار ختم ہو گیا۔\n53۔ تو باپ نے جان لیا کہ {یہ} اسی وقت تھا جب یسوع نے اسے کہا، تیرا بیٹا زندہ ہے: اور خود ایمان لایا اور اس کا پورا گھر۔\n54۔ یہ بھی دوسرا معجزہ ہے جو یسوع نے کیا، جب وہ یہودیہ سے گلیل میں آئے۔","1۔ اس کے بعد یہودیوں کی عید ہوتی تھی؛ اور یسوع یروشلم چلے گئے۔\n2۔ اب یروشلم میں بھیڑ کے بازار کے پاس ایک تالاب ہے، جسے عبرانی زبان میں Bethesda کہا جاتا ہے، جس میں پانچ برآمدے ہیں۔ {مارکیٹ: یا، گیٹ}\n3۔ ان میں بے بس لوگوں کی بڑی تعداد تھی، اندھے، رکے ہوئے، مرجھائے ہوئے، پانی کے بہاؤ کے انتظار میں۔\n4۔ کیونکہ ایک فرشتہ ایک خاص موسم میں تالاب میں اترا اور پانی کو تنگ کرتا: جو بھی پانی کی خرابی کے بعد سب سے پہلے داخل ہوا، وہ اپنی بیماری سے پاک ہو گیا۔\n5۔ اور وہاں ایک شخص تھا، جسے تیس سال سے بیماری تھی۔\n6۔ جب یسوع نے اسے جھوٹ بولتے دیکھا، اور جان لیا کہ وہ اب کافی عرصہ ہو چکا ہے، تو اس نے اس سے کہا، کیا تم مکمل ہو جاؤ گے؟\n7۔ نامرد آدمی نے جواب دیا، جناب، جب پانی میں ہلچل ہو تو میرے پاس کوئی آدمی نہیں ہے جو مجھے تالاب میں ڈالے، لیکن جب میں آ رہا ہوں، تو میرے سامنے ایک اور سیڑھی نیچے آ جائے۔\n8۔ یسوع اس سے فرماتا ہے، اٹھو، اپنا بستر اٹھو اور چلو۔\n9۔ اور فورا وہ آدمی صحت یاب ہو گیا، بستر پر اٹھا اور چلنے لگا: اور اسی دن سبت تھا۔\n10۔ یہودیوں نے اس سے کہا جو شفا پایا ہے، یہ ہفتہ کا دن ہے: تمہیں اپنا بستر اٹھانا جائز نہیں۔\n11۔ اس نے جواب دیا، جس نے مجھے مکمل کیا، اسی نے مجھ سے کہا، اپنا بستر اٹھو اور چلو۔\n12۔ پھر انہوں نے اس سے پوچھا، وہ کون سا آدمی ہے جس نے تم سے کہا، اپنا بستر اٹھو اور چلو؟\n13۔ اور جو شفا پایا تھا، وہ نہیں تھا کہ وہ کون تھا: کیونکہ یسوع نے خود کو وہاں سے منتقل کر دیا تھا، ایک ہجوم کی تعداد {وہاں} جگہ پر۔ {ایک ہجوم...: یا، اس ہجوم میں سے}\n14۔ اس کے بعد یسوع اسے ہیکل میں پاتا ہے اور اس سے کہتا ہے، دیکھو، تم پاک ہو گئے ہو: مزید گناہ نہ کرو، ورنہ تمہیں اس سے برا کچھ مل جائے گا۔\n15۔ وہ آدمی چلا گیا، اور یہودیوں کو بتایا کہ یسوع ہی تھا جس نے اسے مکمل کیا۔\n16۔ اسی لیے یہودیوں نے یسوع کو ستایا اور اسے قتل کرنے کی کوشش کی، کیونکہ اس نے یہ سب سبت کے دن کیا تھا۔\n17۔ لیکن یسوع نے ان کا جواب دیا، میرا باپ اب تک کام کرتا ہے، اور میں کام کرتا ہوں۔\n18۔ اسی لیے یہودیوں نے اسے مارنے کی کوشش کی، کیونکہ اس نے نہ صرف سبت توڑا بلکہ یہ بھی کہا کہ خدا اس کا باپ ہے، اور خود کو خدا کے برابر بنایا۔\n19۔ پھر یسوع نے جواب دیا اور ان سے کہا، \"یقینا، واقعی، میں تم سے کہتا ہوں، بیٹا اپنے بارے میں کچھ نہیں کر سکتا سوائے اس کے جو وہ باپ کو کرتے دیکھتا ہے: کیونکہ جو کچھ وہ کرتا ہے، وہ بیٹے کے لیے بھی کرتا ہے۔\n20۔ کیونکہ باپ بیٹے سے محبت کرتا ہے، اور اسے وہ سب کچھ دکھاتا ہے جو وہ خود کرتا ہے: اور وہ اسے ان سے بڑے کام دکھائے گا تاکہ تم حیران ہو جاؤ۔\n21۔ کیونکہ جیسے باپ مردوں کو زندہ کرتا ہے، اور انہیں زندہ کرتا ہے؛ اسی طرح بیٹا جسے چاہے زندہ کرتا ہے۔\n22۔ کیونکہ باپ کسی کا فیصلہ نہیں کرتا، بلکہ اس نے تمام فیصلے بیٹے کے سپرد کیے ہیں:\n23۔ کہ تمام لوگ بیٹے کی عزت کریں، جیسے وہ باپ کی عزت کرتے ہیں۔ جو بیٹے کی عزت نہیں کرتا وہ اس باپ کی عزت نہیں کرتا جس نے اسے بھیجا ہے۔\n24. واقعی، واقعی، میں تم سے کہتا ہوں، جو میرا کلام سنتا ہے اور اس پر ایمان رکھتا ہے جس نے مجھے بھیجا، وہ ہمیشہ کی زندگی پاتا ہے اور ملامت میں نہیں آئے گا؛ لیکن موت سے زندگی میں منتقل ہو جاتا ہے۔\n25. واقعی، واقعی، میں تم سے کہتا ہوں، وقت آ رہا ہے، اور اب آ گیا ہے، جب مردے خدا کے بیٹے کی آواز سنیں گے: اور جو سنیں گے وہ زندہ ہوں گے۔\n26۔ کیونکہ جیسے باپ اپنے اندر زندگی رکھتا ہے؛ اسی طرح اس نے بیٹے کو اپنے اندر زندگی دینے کا حق دیا ہے؛\n27۔ اور اسے حکم دینے کا اختیار بھی دیا ہے، کیونکہ وہ انسان کا بیٹا ہے۔\n28۔ اس پر حیران نہ ہو: کیونکہ وہ وقت آ رہا ہے، جس میں قبروں میں موجود سب اس کی آواز سنیں گے،\n29۔ اور باہر آئے گا؛ جنہوں نے زندگی کی قیامت کے لیے بھلائی کی ہے؛ اور وہ جنہوں نے برائی کی، عذاب کی دوبارہ زندہ ہونے کی طرف میں۔\n30۔ میں خود کچھ نہیں کر سکتا: جیسا کہ میں سنتا ہوں، میں فیصلہ کرتا ہوں: اور میرا فیصلہ منصفانہ ہے؛ کیونکہ میں اپنی مرضی نہیں چاہتا، بلکہ اس باپ کی مرضی چاہتا ہوں جس نے مجھے بھیجا ہے۔\n31. اگر میں خود گواہی دوں تو میری گواہی سچ نہیں ہے۔\n32. ایک اور ہے جو میرے بارے میں گواہ ہے؛ اور میں جانتا ہوں کہ جو گواہی وہ میرے بارے میں دیتا ہے وہ سچ ہے۔\n33۔ تم نے یوحنا کو بھیجا، اور وہ سچائی کی گواہی دی۔\n34۔ لیکن مجھے انسان سے گواہی نہیں ملتی بلکہ یہ باتیں میں کہتا ہوں تاکہ تم نجات پا سکو۔\n35۔ وہ جلتا ہوا اور چمکتا ہوا روشنی تھا: اور تم اس کی روشنی میں خوشی منانے کے لیے ایک موسم کے لیے تیار تھے۔\n36۔ لیکن میرے پاس یوحنا کی گواہی سے زیادہ بڑی گواہی ہے: کیونکہ جو کام باپ نے مجھے مکمل کرنے کے لیے دیے ہیں، وہی کام جو میں کرتا ہوں، میرے لیے گواہی دیتے ہیں کہ باپ نے مجھے بھیجا ہے۔\n37۔ اور خود باپ، جس نے مجھے بھیجا ہے، نے میری گواہی دی ہے۔ تم نے نہ تو اس کی آواز سنی ہے، نہ ہی اس کی شکل دیکھی ہے۔\n38۔ اور اس کا کلام آپ میں قائم نہیں رہتا: جس کے لیے اس نے بھیجا ہے، آپ اس پر یقین نہیں کرتے۔\n39۔ صحیفوں کی تلاش کریں؛ کیونکہ تم سمجھتے ہو کہ ان میں تمہیں ابدی زندگی حاصل ہے: اور وہی میرے بارے میں گواہی دیتے ہیں۔\n40۔ اور تم میرے پاس نہیں آؤ گے، تاکہ تمہیں زندگی مل سکے۔\n41۔ مجھے مردوں سے عزت نہیں ملتی۔\n42۔ لیکن میں تمہیں جانتا ہوں کہ تم میں خدا کی محبت نہیں ہے۔\n43. میں اپنے باپ کے نام پر آیا ہوں، اور تم مجھے قبول نہیں کرتے: اگر کوئی اور اپنے نام پر آئے گا، تو تم اسے پاؤ گے۔\n44۔ آپ کیسے ایمان لائیں گے، جو ایک دوسرے کی عزت حاصل کرتے ہیں، اور وہ عزت نہیں چاہتے جو صرف خدا کی طرف سے آتی ہے؟\n45. یہ نہ سمجھو کہ میں تمہیں باپ کے سامنے الزام دوں گا: ایک ہے جو تم پر الزام لگاتا ہے، حتیٰ کہ موسیٰ بھی، جس پر تم بھروسہ کرتے ہو۔\n46۔ کیونکہ اگر تم موسیٰ پر یقین کرتے، تو مجھ پر یقین کرتے: کیونکہ اس نے میرے بارے میں لکھا۔\n47۔ لیکن اگر آپ اس کی تحریروں پر یقین نہیں کرتے، تو میرے الفاظ پر کیسے یقین کریں گے؟","1۔ ان واقعات کے بعد یسوع گلیل کے سمندر کے پار گئے، جو کہ طبریہ کا {سمندر} ہے۔\n2۔ اور اس کے پیچھے بہت سے لوگ آئے، کیونکہ انہوں نے اس کے معجزات دیکھے جو اس نے ان پر کیے جو بیمار تھے۔\n3۔ اور یسوع پہاڑ پر چڑھے، اور وہاں اپنے شاگردوں کے ساتھ بیٹھے رہے۔\n4۔ اور فسح، جو یہودیوں کا عید تھا، قریب تھا۔\n5۔ جب یسوع نے اپنی آنکھیں اٹھائیں اور ایک بڑی جماعت کو اپنے پاس آتے دیکھا، تو اس نے فلپ سے کہا، ہم کہاں سے روٹی خریدیں تاکہ یہ کھائیں؟\n6۔ اور یہ اس نے ثابت کرنے کے لیے کہا: کیونکہ وہ خود جانتا تھا کہ وہ کیا کرے گا۔\n7۔ فلپ نے جواب دیا، دو سو پینی کی روٹی ان کے لیے کافی نہیں، تاکہ ہر ایک تھوڑا سا لے سکے۔\n8۔ اس کے ایک شاگرد، اینڈریو، جو شمعون پطرس کا بھائی ہے، اس سے کہتا ہے،\n9۔ یہاں ایک لڑکا ہے، جس کے پاس پانچ جو کی روٹیاں اور دو چھوٹی مچھلیاں ہیں: لیکن وہ اتنی زیادہ مچھلیوں میں کیا ہیں؟\n10۔ اور یسوع نے کہا، مردوں کو بٹھا دو۔ اب جگہ پر کافی گھاس تھی۔ تو مرد بیٹھ گئے، تقریبا پانچ ہزار کی تعداد میں۔\n11۔ اور یسوع نے روٹیاں لے لیں؛ اور جب اس نے شکر ادا کیا، تو اس نے شاگردوں میں تقسیم کی، اور شاگردوں کو جو اترے گئے تھے؛ اور مچھلیوں کے لیے بھی جتنا وہ چاہیں۔\n12۔ جب وہ بھر گئے، تو اس نے اپنے شاگردوں سے کہا، جو ٹکڑے باقی ہیں انہیں جمع کرو، تاکہ کچھ بھی ضائع نہ ہو۔\n13۔ اس لیے انہوں نے انہیں اکٹھا کیا، اور بارہ ٹوکریاں پانچ جو کی روٹیوں کے ٹکڑوں سے بھر دیں، جو ان لوگوں کے اوپر رہ گئیں جنہوں نے کھایا تھا۔\n14۔ پھر ان لوگوں نے، جب انہوں نے وہ معجزہ دیکھا جو یسوع نے کیا، تو کہا، یہ وہ سچائی ہے جو نبی کو دنیا میں آنا چاہیے۔\n15۔ جب یسوع نے محسوس کیا کہ وہ اسے زبردستی لے جائیں گے اور اسے بادشاہ بنائیں گے، تو وہ خود اکیلا پہاڑ کی طرف روانہ ہو گیا۔\n16۔ اور جب {اب} آیا، اس کے شاگرد سمندر کی طرف چلے گئے،\n17۔ اور ایک جہاز میں سوار ہوا اور سمندر کے پار کفرناحوم کی طرف روانہ ہوا۔ اور اب اندھیرا تھا، اور یسوع ان کے پاس نہیں آیا تھا۔\n18۔ اور سمندر ایک تیز ہوا کی وجہ سے اٹھا۔\n19۔ تو جب وہ تقریبا پانچ، بیس یا تیس فرلانگ چلا چکے تھے، تو انہوں نے یسوع کو سمندر پر چلتے اور جہاز کے قریب آتے دیکھا: اور وہ ڈر گئے۔\n20۔ لیکن وہ ان سے کہتا ہے، یہ میں ہوں؛ ڈریں نہیں۔\n21۔ پھر انہوں نے خوش دلی سے اسے جہاز میں قبول کیا: اور فورا جہاز اس زمین پر پہنچ گیا جہاں وہ گئے تھے۔\n22۔ اگلے دن، جب سمندر کے دوسری طرف کھڑے لوگوں نے دیکھا کہ وہاں کوئی اور کشتی نہیں ہے، سوائے اس کشتی کے جس میں اس کے شاگرد سوار تھے، اور یسوع اپنے شاگردوں کے ساتھ کشتی میں نہیں گیا، بلکہ اس کے شاگرد اکیلے چلے گئے تھے؛\n23۔ (اگرچہ طبریہ سے دوسری کشتیاں اس جگہ پہنچیں جہاں انہوں نے روٹی کھائی، اس کے بعد خداوند نے شکر ادا کیا:)\n24۔ جب لوگوں نے دیکھا کہ یسوع وہاں نہیں ہے، نہ اس کے شاگرد، تو وہ بھی جہاز پر سوار ہوئے اور یسوع کی تلاش میں کفرناحوم آئے۔\n25۔ اور جب انہوں نے اسے سمندر کے دوسری طرف پایا، تو انہوں نے کہا، ربی، تم یہاں کب آئے ہو؟\n26۔ یسوع نے ان کا جواب دیا اور کہا، \"واقعی، یقینا، میں تم سے کہتا ہوں، تم مجھے تلاش کرتے ہو، نہ کہ معجزات دیکھ کر، بلکہ اس لیے کہ تم نے روٹیاں کھائی اور بھر گئے۔\n27۔ اس گوشت کے لیے محنت نہ کرو جو مر جاتا ہے، بلکہ اس گوشت کے لیے محنت کرو جو ابدی زندگی تک قائم رہتا ہے، جو انسان کا بیٹا تمہیں دے گا: کیونکہ خدا باپ اس کے لیے مہر لگا چکا ہے۔ {محنت نہ کرو: یا، کام نہ کرو}\n28۔ پھر انہوں نے اس سے کہا، ہم کیا کریں، تاکہ ہم خدا کے کام کر سکیں؟\n29۔ یسوع نے جواب دیا اور ان سے کہا، یہ خدا کا کام ہے، جس پر تم ایمان رکھتے ہو جسے اس نے بھیجا ہے۔\n30۔ اس لیے انہوں نے اس سے کہا، تو تم کیا نشان دکھاتے ہو تاکہ ہم تم کو دیکھ سکیں اور یقین کریں؟ تم کیا کرتے ہو؟\n31۔ ہمارے آباؤ اجداد صحرا میں من کھاتے تھے؛ جیسا کہ لکھا ہے، اس نے انہیں آسمان سے روٹی دی تاکہ وہ کھا سکیں۔\n32۔ پھر یسوع نے ان سے کہا، \"واقعی، واقعی، میں تم سے کہتا ہوں، موسیٰ نے تمہیں آسمان سے وہ روٹی نہیں دی؛ لیکن میرا باپ تمہیں آسمان سے سچی روٹی دیتا ہے۔\n33۔ کیونکہ خدا کی روٹی وہ ہے جو آسمان سے اترتی ہے اور دنیا کو زندگی دیتی ہے۔\n34۔ پھر انہوں نے اس سے کہا، اے خداوند، ہمیشہ ہمیں یہ روٹی دے دے۔\n35۔ اور یسوع نے ان سے کہا، میں زندگی کی روٹی ہوں: جو میرے پاس آئے گا وہ کبھی بھوکا نہیں ہوگا؛ اور جو مجھ پر ایمان لائے گا وہ کبھی پیاسا نہیں ہوگا۔\n36. لیکن میں نے تم سے کہا، کہ تم نے بھی مجھے دیکھا ہے، اور یقین نہیں رکھتے۔\n37۔ جو کچھ باپ مجھے دیتا ہے وہ سب میرے پاس آ جائے گا؛ اور جو میرے پاس آئے گا اسے میں کبھی نکالوں گا نہیں۔\n38۔ کیونکہ میں آسمان سے اترا، اپنی مرضی کے مطابق نہیں، بلکہ اس کی مرضی سے جس نے مجھے بھیجا ہے۔\n39۔ اور یہ باپ کی مرضی ہے جس نے مجھے بھیجا ہے، جو کچھ اس نے مجھے دیا ہے اس میں سے میں کچھ نہیں کھوؤں گا، بلکہ آخری دن اسے دوبارہ زندہ کروں گا۔\n40۔ اور یہ اس کی مرضی ہے جس نے مجھے بھیجا، تاکہ ہر وہ شخص جو بیٹے کو دیکھے اور اس پر ایمان لے، اسے دائمی زندگی ملے: اور میں اسے آخری دن زندہ کروں گا۔\n41۔ یہودیوں نے پھر اس پر سرگوشی کی، کیونکہ اس نے کہا، میں وہ روٹی ہوں جو آسمان سے آئی ہے۔\n42۔ اور انہوں نے کہا، کیا یہ یسوع نہیں ہے، یوسف کا بیٹا، جس کے والد اور والدہ کو ہم جانتے ہیں؟ تو پھر وہ کیسے کہتا ہے، میں آسمان سے نیچے آیا ہوں؟\n43۔ یسوع نے جواب دیا اور ان سے کہا، آپس میں سرگوشی نہ کرو۔\n44۔ کوئی شخص میرے پاس نہیں آ سکتا، سوائے اس باپ کے جس نے مجھے بھیجا ہے، اسے کھینچ لیتا ہوں: اور میں اسے آخری دن زندہ کروں گا۔\n45۔ یہ نبیوں میں لکھا ہے، اور سب کو خدا کے بارے میں تعلیم دی جائے گی۔ لہٰذا ہر وہ شخص جو باپ کے بارے میں سنا اور جانا، میرے پاس آتا ہے۔\n46۔ یہ نہیں کہ کسی نے باپ کو دیکھا ہو، سوائے اس کے جو خدا کا ہے، اس نے باپ کو دیکھا ہے۔\n47۔ واقعی، یقینا، میں تم سے کہتا ہوں، جو مجھ پر ایمان رکھتا ہے وہ ہمیشہ کی زندگی رکھتا ہے۔\n48۔ میں زندگی کی وہ روٹی ہوں۔\n49۔ تمہارے آباؤ اجداد نے جنگل میں من کھایا تھا، اور وہ مر چکے ہیں۔\n50۔ یہ وہ روٹی ہے جو آسمان سے آتی ہے، تاکہ انسان اس میں سے کھا سکے اور مر نہ جائے۔\n51. میں وہ زندہ روٹی ہوں جو آسمان سے آیا ہے: جو کوئی اس روٹی سے کھائے گا تو وہ ہمیشہ زندہ رہے گا: اور جو روٹی میں دوں گا وہ میرا گوشت ہے، جو میں دنیا کی زندگی کے لیے دوں گا۔\n52۔ یہودیوں نے آپس میں لڑائی کی، کہنے لگے، یہ آدمی ہمیں اپنا گوشت کھانے کے لیے کیسے دے سکتا ہے؟\n53۔ پھر یسوع نے ان سے کہا، \"واقعی، یقینا، میں تم سے کہتا ہوں، جب تک تم انسان کے بیٹے کا گوشت نہ کھاؤ اور اس کا خون نہ پیو، تم میں کوئی جان نہیں۔\n54۔ جو میرا گوشت کھاتا ہے اور میرا خون پیتا ہے، اس کی زندگی ہمیشہ کے لیے ہے؛ اور میں اسے آخری دن اٹھاؤں گا۔\n55۔ کیونکہ میرا گوشت واقعی گوشت ہے، اور میرا خون واقعی شراب ہے۔\n56۔ جو میرا گوشت کھاتا ہے اور میرا خون پیتا ہے، وہ میرے اندر رہتا ہے، اور میں اس میں۔\n57۔ جیسے زندہ باپ نے مجھے بھیجا ہے، اور میں باپ کے ذریعے جیتا ہوں: ویسے ہی جو مجھے کھاتا ہے، وہ بھی میرے ساتھ زندہ رہے گا۔\n58۔ یہ وہ روٹی ہے جو آسمان سے اتری: نہ کہ جیسے تمہارے آباؤ اجداد نے من کھایا اور مر گئے: جو اس روٹی سے کھائے گا وہ ہمیشہ زندہ رہے گا۔\n59۔ یہ باتیں اس نے کنیساگوگ میں کہی تھیں، جیسا کہ وہ کفرناحوم میں پڑھاتے تھے۔\n60۔ لہٰذا اس کے بہت سے شاگردوں نے جب یہ سنا تو کہا، یہ ایک سخت قول ہے؛ کون سن سکتا ہے؟\n61۔ جب یسوع نے اپنے اندر جانا کہ اس کے شاگرد اس پر سرگوشی کر رہے ہیں، تو اس نے ان سے کہا، کیا یہ تمہیں ناگوار گزرتا ہے؟ {ناراض: یا، بدنام کرنا، یا، تمہیں لڑکھڑانے پر مجبور کرنا}\n62. {کیا} اور اگر تم دیکھو کہ انسان کا بیٹا وہاں چڑھتا ہے جہاں وہ پہلے تھا؟\n63. روح زندہ کرتی ہے؛ جسم کو کچھ فائدہ نہیں: جو الفاظ میں تم سے کہتا ہوں، {وہ} روح ہیں، اور {وہ} زندگی ہیں۔\n64۔ لیکن آپ میں سے کچھ لوگ ایسا نہیں مانتے۔ کیونکہ یسوع شروع سے جانتے تھے کہ وہ کون ہیں جو ایمان نہیں رکھتے اور کون اسے دھوکہ دے گا۔\n65۔ اور اس نے کہا، لہٰذا میں نے تم سے کہا کہ کوئی آدمی میرے پاس نہیں آ سکتا، جب تک کہ وہ میرے والد کی طرف سے نہ دیا جائے۔\n66۔ اس {وقت} سے اس کے بہت سے شاگرد واپس چلے گئے، اور اس کے ساتھ مزید نہیں چلے۔\n67۔ پھر یسوع نے بارہ سے کہا، کیا تم بھی چلے جاؤ گے؟\n68۔ پھر شمعون پطرس نے جواب دیا، اے خداوند، ہم کس کے پاس جائیں؟ تمہارے پاس ابدی زندگی کے الفاظ ہیں۔\n69۔ اور ہم ایمان رکھتے ہیں اور یقین رکھتے ہیں کہ تو وہی مسیح ہو، زندہ خدا کا بیٹا۔\n70۔ یسوع نے ان کا جواب دیا، کیا میں نے تمہیں بارہ منتخب نہیں کیا، اور تم میں سے ایک شیطان ہے؟\n71۔ اس نے یہودا اسخریوطی [شمعون کا بیٹا} کے بارے میں کہا: کیونکہ وہی تھا جو اسے دھوکہ دے گا، کیونکہ وہ بارہ میں سے ایک تھا۔","1۔ ان واقعات کے بعد یسوع گلیل میں چلے گا: کیونکہ وہ یہودیت میں نہیں چلنا چاہتا تھا، کیونکہ یہودیوں نے اسے مارنے کی کوشش کی۔\n2۔ اب یہودیوں کا خیمہ جات کا جشن قریب تھا۔\n3۔ اس کے بھائیوں نے اس سے کہا، یہاں سے چلے جاؤ اور یہودیہ میں جاؤ، تاکہ تمہارے شاگرد بھی تمہارے کیے ہوئے کام دیکھ سکیں۔\n4۔ کیونکہ {ایسا کوئی انسان} نہیں جو کچھ خفیہ طور پر کرتا ہے، اور وہ خود چاہتا ہے کہ اسے کھلے عام معلوم کیا جائے۔ اگر تم یہ سب کرو گے تو دنیا کے سامنے خود کو ظاہر کرو۔\n5۔ کیونکہ اس کے بھائیوں نے بھی اس پر یقین نہیں کیا۔\n6۔ پھر یسوع نے ان سے کہا، میرا وقت ابھی نہیں آیا، لیکن تمہارا وقت ہمیشہ تیار ہے۔\n7. دنیا آپ سے نفرت نہیں کر سکتی؛ لیکن یہ مجھ سے نفرت کرتا ہے، کیونکہ میں اس کی گواہی دیتا ہوں، کہ ان کے اعمال برے ہیں۔\n8۔ اس دعوت کے لیے چلو: میں ابھی اس دعوت میں نہیں جاتا؛ کیونکہ میرا وقت ابھی مکمل نہیں ہوا۔\n9۔ جب اس نے یہ الفاظ ان سے کہے، تو وہ {ابھی} گلیل میں رہا۔\n10۔ لیکن جب اس کے بھائی اوپر چلے گئے، تو وہ بھی دعوت میں چلا گیا، کھلے عام نہیں بلکہ خفیہ طور پر۔\n11۔ پھر یہودیوں نے دعوت میں اسے تلاش کیا اور کہا، وہ کہاں ہے؟\n12۔ اور لوگوں میں اس کے بارے میں بہت سرگوشیاں ہوئیں: کچھ لوگوں نے کہا، وہ اچھا انسان ہے؛ کچھ نے کہا، نہیں؛ لیکن وہ لوگوں کو دھوکہ دیتا ہے۔\n13۔ تاہم کسی نے یہودیوں کے خوف سے اس کے بارے میں کھل کر بات نہیں کی۔\n14۔ اب عید کے وسط میں یسوع مندر میں گئے اور تعلیم دی۔\n15۔ اور یہودیوں نے حیرت سے کہا، یہ آدمی خطوط کیسے جانتا ہے، حالانکہ وہ کبھی نہیں سیکھا؟ {خطوط: یا، سیکھنا}\n16۔ یسوع نے ان کا جواب دیا اور کہا، میری تعلیم میری نہیں بلکہ اس کی ہے جس نے مجھے بھیجا۔\n17۔ اگر کوئی شخص اپنی مرضی پوری کرے گا، تو وہ عقیدے سے واقف ہوگا، چاہے وہ خدا کی ہو، یا میں اپنے بارے میں بات کر رہا ہوں۔\n18۔ جو اپنے بارے میں بات کرتا ہے وہ اپنی شان کی تلاش میں ہے: لیکن جو اپنی عظمت چاہتا ہے جس نے اسے بھیجا ہے، وہ سچ ہے، اور اس میں کوئی ناانصافی نہیں۔\n19۔ کیا موسیٰ نے تمہیں شریعت نہیں دی تھی، اور پھر بھی تم میں سے کوئی بھی قانون کی پابندی نہیں کرتا؟ تم مجھے مارنے والے کیوں ہو؟\n20۔ لوگوں نے جواب دیا اور کہا، \"تیرا شیطان ہے: کون تمہیں مارنے جا رہا ہے؟\n21۔ یسوع نے جواب دیا اور ان سے کہا، میں نے ایک کام کیا ہے، اور تم سب حیران ہو۔\n22. موسیٰ نے آپ کو ختنہ دیا؛ (اس لیے نہیں کہ یہ موسیٰ کی ہے، بلکہ آباؤ اجداد کی ہے؛) اور تم سبت کے دن ایک آدمی کا ختنہ کرو۔\n23۔ اگر کوئی شخص ہفتہ کے دن ختنہ کروائے، تو موسیٰ کے قانون کی خلاف ورزی نہ ہو؛ کیا تم مجھ سے ناراض ہو، کیونکہ میں نے ہفتہ کے دن ایک آدمی کو پورا کر دیا ہے؟ {وہ...: یا، موسیٰ کے قانون کو توڑے بغیر}\n24. ظاہری شکل کے مطابق فیصلہ نہ کرو، بلکہ نیک فیصلے کا فیصلہ کرو۔\n25۔ پھر یروشلم کے کچھ لوگوں نے کہا، کیا یہ وہی نہیں جسے وہ مارنا چاہتے ہیں؟\n26۔ لیکن دیکھو، وہ جرات مندی سے بولتا ہے، اور وہ اس سے کچھ نہیں کہتے۔ کیا حکمرانوں کو واقعی معلوم ہے کہ یہی مسیح ہے؟\n27۔ چاہے ہم اس آدمی کو جانتے ہوں کہ وہ کہاں سے آیا ہے: لیکن جب مسیح آتا ہے، تو کوئی نہیں جانتا کہ وہ کہاں سے آیا ہے۔\n28۔ پھر یسوع نے مندر میں پکارا، جب اس نے تعلیم دی، کہا، تم دونوں مجھے جانتے ہو، اور جانتے ہو کہ میں کہاں سے آیا ہوں: اور میں خود نہیں آیا، بلکہ جس نے مجھے بھیجا وہ سچا ہے، جسے تم نہیں جانتے۔\n29۔ لیکن میں اسے جانتا ہوں: کیونکہ میں اس کی طرف سے ہوں، اور اس نے مجھے بھیجا ہے۔\n30۔ پھر انہوں نے اسے پکڑنے کی کوشش کی، لیکن کسی نے اس پر ہاتھ نہیں اٹھایا، کیونکہ اس کا وقت ابھی نہیں آیا تھا۔\n31۔ اور بہت سے لوگوں نے اس پر ایمان لایا اور کہا، جب مسیح آئے گا، کیا وہ ان معجزات سے زیادہ کرے گا جو اس انسان نے کیے ہیں؟\n32۔ فریسیوں نے سنا کہ لوگ اس کے بارے میں ایسی باتیں کرتے ہیں؛ اور فریسیوں اور چیف کاهنوں نے افسران بھیجے کہ وہ اسے لے جائیں۔\n33۔ پھر یسوع نے ان سے کہا، پھر بھی میں تھوڑی دیر تمہارے ساتھ ہوں، اور پھر میں اس کے پاس جاتا ہوں جس نے مجھے بھیجا۔\n34۔ تم مجھے تلاش کرو گے، اور مجھے نہیں پاؤ گے: اور جہاں میں ہوں، وہاں تم نہیں جا سکتے۔\n35۔ پھر یہودیوں نے آپس میں کہا، وہ کہاں جائے گا، کہ ہم اسے نہیں پائیں گے؟ کیا وہ غیر یہودیوں میں بکھرے ہوئے لوگوں کے پاس جائے گا، اور غیر قوموں کو تعلیم دے گا؟ {غیر یہودی: یا، یونانی}\n36۔ یہ کون سا {طریقہ} ہے کہ اس نے کہا، تم مجھے تلاش کرو گے، اور {مجھ} نہیں پاؤ گے: اور جہاں میں ہوں، {وہاں} تم نہیں جا سکتے؟\n37۔ آخری دن، یعنی تہوار کے اس عظیم دن، یسوع کھڑے ہو کر روتے ہوئے کہا، اگر کسی کو پیاس لگے تو وہ میرے پاس آ کر پی لے۔\n38۔ جو مجھ پر ایمان لائے گا، جیسا کہ کتاب مقدس نے کہا ہے، اس کے پیٹ سے زندہ پانی کی ندیاں نکلیں گی۔\n39۔ (لیکن یہ اس نے روح کے بارے میں کہا، جو اس پر ایمان لانے والوں کو ملنا چاہیے: کیونکہ روح القدس ابھی {دیا نہیں گیا}؛ کیونکہ وہ یسوع ابھی جلال یافتہ نہیں ہوا تھا۔)\n40۔ لہٰذا بہت سے لوگوں نے جب یہ کہاوت سنی تو کہا، ایک سچائی کے بارے میں یہ نبی ہے۔\n41۔ دوسروں نے کہا، یہی مسیح ہے۔ لیکن کچھ نے کہا، کیا مسیح گلیل سے باہر آئے گا؟\n42. کیا صحیفہ میں نہیں لکھا کہ مسیح داؤد کی نسل سے آیا ہے، اور بیت لحم کے شہر سے آیا ہے، جہاں داؤد تھا؟\n43۔ تو اس کی وجہ سے لوگوں میں تقسیم ہوئی۔\n44۔ اور ان میں سے کچھ اسے لے جاتے؛ لیکن کسی نے اس پر ہاتھ نہیں اٹھایا۔\n45۔ پھر افسران سردار کاهنوں اور فریسیوں کے پاس آئے؛ اور انہوں نے ان سے کہا، تم نے اسے کیوں نہیں لایا؟\n46۔ افسران نے جواب دیا، کبھی بھی اس آدمی کی طرح بات نہیں کی۔\n47۔ پھر فریسیوں نے جواب دیا، کیا تم بھی دھوکہ کھا گئے ہو؟\n48۔ کیا کسی حکمران یا فریسی نے اس پر ایمان لایا؟\n49۔ لیکن یہ لوگ جو قانون نہیں جانتے، لعنت زدہ ہیں۔\n50. نیکودیمس ان سے کہتا ہے، (جو رات کو یسوع کے پاس آیا، وہ ان میں سے ایک ہے،) {یسوع سے: اس کے لیے گرینل}\n51۔ کیا ہمارا قانون کسی انسان کو اس سے پہلے پرکھتا ہے کہ وہ اسے سنے اور جانتا ہے کہ وہ کیا کرتا ہے؟\n52۔ انہوں نے جواب دیا اور اس سے کہا، کیا تم بھی گلیل کے ہو؟ تلاش کرو، اور دیکھو: کیونکہ گلیل سے کوئی نبی نہیں آتا۔\n53۔ اور ہر آدمی اپنے گھر چلا گیا۔","1۔ یسوع زیتون کے پہاڑ پر گئے۔\n2۔ اور صبح سویرے وہ دوبارہ مندر میں آیا، اور سب لوگ اس کے پاس آ گئے؛ اور وہ بیٹھ گیا، اور انہیں پڑھایا۔\n3۔ اور کاتب اور فریسیوں نے اس کے پاس ایک عورت لائی جو میں لی گئی تھی؛ اور جب انہوں نے اسے بیچ میں رکھا،\n4۔ وہ اس سے کہتے ہیں، مالک، اس عورت کو کے جرم میں اغوا کیا گیا تھا، اسی عمل کے دوران۔\n5۔ اب موسیٰ نے شریعت میں ہمیں حکم دیا کہ ایسے لوگ سنگسار کیے جائیں: لیکن تم کیا کہتے ہو؟\n6۔ یہ انہوں نے کہا، اسے بہکانے کے لیے، کہ شاید انہیں اس پر الزام لگانا پڑے۔ لیکن یسوع جھک گیا، اور {اپنی} انگلی سے زمین پر لکھا، {گویا اس نے انہیں سنا ہی نہ ہو}۔\n7۔ جب وہ اس سے پوچھتے رہے، تو اس نے خود کو اٹھایا اور کہا، جو تم میں سے بے گناہ ہے، وہ پہلے اس پر پتھر پھینکے۔\n8۔ اور پھر وہ جھک گیا، اور زمین پر لکھنے لگا۔\n9۔ اور جنہوں نے یہ سنا، اپنے ضمیر کی وجہ سے سزا پا کر، ایک ایک کر کے باہر نکل گئے، سب سے بڑے سے شروع ہو کر آخر تک: اور یسوع اکیلا رہ گیا، اور عورت درمیان میں کھڑی تھی۔\n10۔ جب یسوع نے خود کو اٹھایا اور صرف عورت کو دیکھا، تو اس نے اس سے کہا، عورت، وہ الزام لگانے والے کہاں ہیں؟ کیا کسی نے تمہیں سزا نہیں دی؟\n11۔ اس نے کہا، کوئی آدمی نہیں، خداوند۔ اور یسوع نے اس سے کہا، نہ میں تمہیں مذمت کرتا ہوں: جاؤ اور مزید گناہ نہ کرو۔\n12۔ پھر یسوع نے دوبارہ ان سے کہا، میں دنیا کی روشنی ہوں: جو میری پیروی کرے گا وہ اندھیرے میں نہیں چلے گا بلکہ زندگی کی روشنی رکھے گا۔\n13۔ فریسیوں نے اس سے کہا، تو اپنے آپ کا ریکارڈ رکھتا ہے؛ تمہارا ریکارڈ سچ نہیں ہے۔\n14۔ یسوع نے جواب دیا اور ان سے کہا، اگرچہ میں اپنے بارے میں ریکارڈ رکھتا ہوں، {لیکن} میرا ریکارڈ سچ ہے: کیونکہ میں جانتا ہوں کہ میں کہاں سے آیا ہوں اور کہاں جا رہا ہوں؛ لیکن تم نہیں بتا سکتے کہ میں کہاں سے آیا ہوں اور کہاں جا رہا ہوں۔\n15۔ تم جسم کے مطابق فیصلہ کرتے ہو؛ میں کسی کا فیصلہ نہیں کرتا۔\n16۔ اور پھر بھی اگر میں فیصلہ کروں تو میرا فیصلہ درست ہے: کیونکہ میں اکیلا نہیں ہوں، بلکہ میں اور وہ باپ ہوں جس نے مجھے بھیجا۔\n17۔ آپ کے قانون میں بھی لکھا ہے کہ دو مردوں کی گواہی سچ ہے۔\n18. میں وہ ہوں جو اپنے آپ کی گواہی دیتا ہے، اور وہ باپ جس نے مجھے بھیجا ہے، میرے بارے میں گواہی دیتا ہے۔\n19۔ پھر انہوں نے اس سے کہا، تمہارا باپ کہاں ہے؟ یسوع نے جواب دیا، تم مجھے نہیں جانتے اور نہ ہی میرے باپ کو: اگر تم مجھے جانتے تو میرے باپ کو بھی جانتے ہوتے۔\n20۔ یہ الفاظ یسوع نے خزانے میں کہا، جیسا کہ انہوں نے مندر میں تعلیم دی: اور کسی نے اس پر ہاتھ نہیں اٹھایا؛ کیونکہ اس کا وقت ابھی نہیں آیا تھا۔\n21۔ پھر یسوع نے دوبارہ ان سے کہا، میں اپنی راہ پر چلتا ہوں، اور تم مجھے تلاش کرو گے، اور اپنے گناہوں میں مر جاؤ گے: جہاں میں جاؤں گا، تم نہیں آؤ گے۔\n22۔ پھر یہودیوں نے کہا، کیا وہ خودکشی کرے گا؟ کیونکہ اس نے کہا، جہاں میں جاؤں، تم نہیں آ سکتے۔\n23۔ اور اس نے ان سے کہا، تم نیچے سے ہو؛ میں اوپر سے ہوں: تم اس دنیا کے ہو؛ میں اس دنیا کا نہیں ہوں۔\n24۔ میں نے تم سے کہا، کہ تم اپنے گناہوں میں مر جاؤ گے: کیونکہ اگر تم یقین نہیں رکھتے کہ میں وہ ہوں، تو تم اپنے گناہوں میں مر جاؤ گے۔\n25۔ پھر انہوں نے اس سے کہا، تم کون ہو؟ اور یسوع ان سے کہتا ہے، وہی {وہی} جو میں نے تم سے شروع سے کہا تھا۔\n26۔ میرے پاس کہنے اور تمہارے بارے میں فیصلہ کرنے کے لیے بہت کچھ ہے: لیکن جس نے مجھے بھیجا وہ سچ ہے؛ اور میں دنیا سے وہ باتیں کرتا ہوں جو میں نے اس کے بارے میں سنی ہیں۔\n27۔ وہ نہیں سمجھتے تھے کہ اس نے ان سے باپ کے بارے میں بات کی۔\n28۔ پھر یسوع نے ان سے کہا، جب تم انسان کے بیٹے کو اٹھا لو گے، تب تم جان لو گے کہ میں {و} ہوں، اور {کہ} میں اپنے بارے میں کچھ نہیں کرتا؛ لیکن جیسا کہ میرے والد نے مجھے سکھایا ہے، میں یہ باتیں کہتا ہوں۔\n29۔ اور جس نے مجھے بھیجا وہ میرے ساتھ ہے: باپ نے مجھے اکیلا نہیں چھوڑا؛ کیونکہ میں ہمیشہ وہ کام کرتا ہوں جو اسے خوش کرتے ہیں۔\n30۔ جب اس نے یہ الفاظ کہے، تو بہت سے لوگ اس پر یقین کر گئے۔\n31۔ پھر یسوع نے ان یہودیوں سے کہا جنہوں نے اس پر ایمان لائی، اگر تم میرے کلام پر قائم رہو، {تو} تم واقعی میرے شاگرد ہو؛\n32. اور تم سچ جان لو گے، اور سچائی تمہیں آزاد کرے گی۔\n33۔ انہوں نے جواب دیا، ہم ابراہیم کی نسل ہیں، اور کبھی کسی انسان کے غلام نہیں تھے: تم کیسے کہتے ہو، تم آزاد ہو جاؤ گے؟\n34۔ یسوع نے ان کا جواب دیا، واقعی، یقینا، میں تم سے کہتا ہوں، جو بھی گناہ کرتا ہے وہ گناہ کا بندہ ہے۔\n35۔ اور خادم ہمیشہ کے لیے گھر میں نہیں رہتا: {بلکہ} بیٹا ہمیشہ رہتا ہے۔\n36۔ اگر بیٹا تمہیں آزاد کرے گا، تو تم واقعی آزاد ہو گے۔\n37۔ میں جانتا ہوں کہ تم ابراہیم کی نسل ہو؛ لیکن تم مجھے مارنا چاہتے ہو، کیونکہ میری بات تم میں کوئی جگہ نہیں۔\n38۔ میں وہی کہتا ہوں جو میں نے اپنے باپ کے ساتھ دیکھا: اور تم وہی کرتے ہو جو تم نے اپنے باپ کے ساتھ دیکھا۔\n39۔ انہوں نے جواب دیا اور اس سے کہا، ابراہیم ہمارا باپ ہے۔ یسوع نے انہیں کہا، اگر تم ابراہیم کے بچے ہوتے تو ابراہیم کے اعمال کرتے۔\n40۔ لیکن اب تم مجھے مارنا چاہتے ہو، ایک آدمی جس نے تمہیں سچ بتایا، جو میں نے خدا کے بارے میں سنا ہے: یہ ابراہیم نہیں تھا۔\n41۔ تم اپنے والد کے کام کرتے ہو۔ پھر انہوں نے اس سے کہا، ہم سے پیدا نہیں ہوئے؛ ہمارے پاس ایک ہی باپ ہے، {حتیٰ کہ} خدا بھی۔\n42۔ یسوع نے ان سے کہا، اگر خدا تمہارا باپ ہوتا تو تم مجھ سے محبت کرتے: کیونکہ میں آگے بڑھا اور خدا کی طرف سے آیا؛ میں بھی خود نہیں آیا، لیکن اس نے مجھے بھیجا۔\n43. تم میری بات کیوں نہیں سمجھتے؟ {حتیٰ کہ} کیونکہ تم میری بات سن نہیں سکتے۔\n44۔ تم اپنے باپ شیطان کے ہو، اور اپنے والد کی خواہشات پوری کرو گے۔ وہ شروع سے ہی قاتل تھا، اور سچائی میں نہیں تھا، کیونکہ اس میں کوئی سچائی نہیں ہے۔ جب وہ جھوٹ بولتا ہے، تو وہ اپنے جھوٹ بولتا ہے: کیونکہ وہ جھوٹا ہے، اور اس کا باپ ہے۔ {اپنی مرضی سے: یا، اپنی مرضی یا مزاج سے}\n45۔ اور چونکہ میں آپ کو سچ بتاتا ہوں، آپ مجھ پر یقین نہیں کرتے۔\n46۔ تم میں سے کون مجھے گناہ پر قائل کرتا ہے؟ اور اگر میں سچ کہوں تو تم مجھ پر یقین کیوں نہیں کرتے؟\n47۔ جو خدا کا ہے وہ خدا کے الفاظ سنتا ہے: اس لیے تم نہیں سنتے، کیونکہ تم خدا کے نہیں ہو۔\n48۔ پھر یہودیوں نے جواب دیا اور اس سے کہا، کیا ہم یہ نہیں کہتے کہ تم سامری ہو اور شیطان ہو؟\n49۔ یسوع نے جواب دیا، میرے پاس شیطان نہیں ہے؛ لیکن میں اپنے باپ کی عزت کرتا ہوں، اور تم واقعی میری بے عزتی کرتے ہو۔\n50۔ اور میں اپنی شان و شوکت نہیں چاہتا: ایک ہے جو تلاش کرتا ہے اور فیصلہ کرتا ہے۔\n51۔ واقعی، واقعی، میں تم سے کہتا ہوں، اگر کوئی میری بات پر قائم رہے تو وہ کبھی موت نہیں دیکھے گا۔\n52۔ پھر یہودیوں نے اس سے کہا، اب ہمیں معلوم ہے کہ تمہارے پاس شیطان ہے۔ ابراہیم مر چکا ہے، اور انبیاء؛ اور تم کہتے ہو، اگر کوئی میری بات پر قائم رہے تو موت کا ذائقہ کبھی نہیں چکھے گا۔\n53۔ کیا تم ہمارے باپ ابراہیم سے بڑا ہو، جو مر چکا ہے؟ اور نبی مر چکے ہیں: تم خود کو کس نے بنایا؟\n54۔ یسوع نے جواب دیا، اگر میں خود کی عزت کروں تو میری عزت کچھ نہیں: یہ میرا باپ ہے جو مجھے عزت دیتا ہے؛ جس کے بارے میں تم کہتے ہو کہ وہ تمہارا خدا ہے:\n55۔ پھر بھی آپ نے اسے نہیں جانا؛ لیکن میں اسے جانتا ہوں: اور اگر میں کہوں کہ میں اسے نہیں جانتا، تو میں تمہاری طرح جھوٹا ہوں گا: لیکن میں اسے جانتا ہوں، اور اس کی باتوں پر قائم رہوں گا۔\n56۔ تمہارے والد ابراہیم نے میرا دن دیکھ کر خوشی منائی: اور اس نے اسے دیکھا اور خوش ہوا۔\n57۔ پھر یہودیوں نے اس سے کہا، تم ابھی پچاس سال کے نہیں ہوئے، اور کیا تم نے ابراہیم کو دیکھا ہے؟\n58۔ یسوع نے ان سے کہا، واقعی، یقینا، میں تم سے کہتا ہوں، ابراہیم سے پہلے میں ہوں۔\n59۔ پھر انہوں نے پتھر اٹھا کر اس پر پھینکے، لیکن یسوع چھپ گیا، اور مندر سے باہر نکل گیا، ان کے درمیان سے گزرتا ہوا گزر گیا۔","1۔ اور جب {یسوع} گزرا، اس نے ایک ایسے آدمی کو دیکھا جو {اپنی پیدائش سے} اندھا تھا۔\n2۔ اور اس کے شاگردوں نے اس سے پوچھا، کہا، استاد، یہ آدمی یا اس کے والدین نے کس نے گناہ کیا کہ وہ اندھا پیدا ہوا؟\n3۔ یسوع نے جواب دیا، نہ اس آدمی نے گناہ کیا، نہ اس کے والدین نے: بلکہ خدا کے اعمال اس میں ظاہر ہوں۔\n4۔ مجھے اس کے کام کرنے ہوں گے جس نے مجھے بھیجا، جب تک دن ہو: رات آتی ہے، جب کوئی انسان کام نہیں کر سکتا۔\n5. جب تک میں دنیا میں ہوں، میں دنیا کی روشنی ہوں۔\n6۔ جب اس نے یہ کہا، تو اس نے زمین پر تھوکا، تھوک سے مٹی بنائی، اور اندھے آدمی کی آنکھوں کو مٹی سے مسح کیا، {مسح کیا گیا...: یا، اندھے آدمی کی آنکھوں پر مٹی پھیلا دی}\n7۔ اور اس سے کہا، جاؤ، سیلوم کے تالاب میں نہاؤ، (جو تشریح کے مطابق بھیجا گیا ہے۔) اس لیے وہ اپنی راہ پر گیا، نہایا اور دیکھنے آیا۔\n8۔ پڑوسیوں نے، اور جنہوں نے پہلے اسے دیکھا تھا کہ وہ اندھا ہے، کہا، کیا یہ وہی نہیں جو بیٹھا اور بھیک مانگ رہا تھا؟\n9۔ کچھ نے کہا، یہ وہ ہے: کچھ نے {کہا}، وہ اس جیسا ہے: {لیکن} اس نے کہا، میں {وہ} ہوں۔\n10۔ لہٰذا انہوں نے اس سے کہا، تمہاری آنکھیں کیسے کھلیں؟\n11۔ اس نے جواب دیا اور کہا، \"ایک آدمی جسے یسوع کہا جاتا ہے، اس نے مٹی بنائی، اور میری آنکھوں کو مسح کیا، اور مجھ سے کہا، سیلوام کے تالاب میں جاؤ اور نہاؤ، اور میں نے غسل کیا، اور میں نے بصیرت حاصل کی۔\n12۔ پھر انہوں نے اس سے کہا، وہ کہاں ہے؟ اس نے کہا، مجھے نہیں معلوم۔\n13۔ انہوں نے فریسیوں کو وہ شخص دیا جو پہلے اندھا تھا۔\n14۔ اور وہ سبت کا دن تھا جب یسوع نے مٹی بنائی، اور اپنی آنکھیں کھولیں۔\n15۔ پھر فریسیوں نے بھی اس سے پوچھا کہ اس نے اپنی بینائی کیسے حاصل کی۔ اس نے ان سے کہا، اس نے میری آنکھوں پر مٹی رکھا، اور میں نے نہلایا، اور دیکھو۔\n16۔ اسی لیے کچھ فریسیوں نے کہا، یہ آدمی خدا کا نہیں ہے، کیونکہ وہ سبت کا دن نہیں رکھتا۔ دوسروں نے کہا، ایک گناہ گار انسان کیسے ایسے معجزے کر سکتا ہے؟ اور ان کے درمیان ایک تقسیم تھی۔\n17۔ وہ اندھے آدمی سے پھر کہتے ہیں، تم اس کے بارے میں کیا کہتے ہو کہ اس نے تمہاری آنکھیں کھول دی ہیں؟ انہوں نے کہا، وہ نبی ہیں۔\n18۔ لیکن یہودیوں نے اس کے بارے میں یقین نہیں کیا کہ وہ نابینا ہے اور اس کی بینائی حاصل کر لی ہے، جب تک کہ انہوں نے اس کے والدین کو بلایا جنہوں نے اس کی بینائی حاصل کی تھی۔\n19۔ اور انہوں نے ان سے پوچھا، کہا، کیا یہ تمہارا بیٹا ہے، جسے تم کہتے ہو کہ وہ اندھا پیدا ہوا؟ تو پھر وہ اب کیسے دیکھتا ہے؟\n20۔ اس کے والدین نے جواب دیا اور کہا، ہم جانتے ہیں کہ یہ ہمارا بیٹا ہے، اور وہ نابینا پیدا ہوا ہے:\n21. لیکن اب وہ کس طرح غصہ کرتا ہے، ہم نہیں جانتے؛ یا کس نے اپنی آنکھیں کھولیں، ہم نہیں جانتے: وہ بالغ ہے؛ اس سے پوچھو: وہ خود بولے گا۔\n22۔ یہ {الفاظ} اس کے والدین نے کہے، کیونکہ وہ یہودیوں سے ڈرتے تھے: کیونکہ یہودیوں نے پہلے ہی اتفاق کر لیا تھا کہ اگر کوئی شخص اعتراف کرے کہ وہ مسیح ہے تو اسے عبادت گاہ سے نکال دیا جائے۔\n23۔ لہٰذا اس کے والدین نے کہا، وہ بالغ ہے؛ اس سے پوچھو۔\n24۔ پھر انہوں نے پھر اندھے آدمی کو بلایا اور کہا، خدا کی تعریف کرو: ہم جانتے ہیں کہ یہ آدمی گناہگار ہے۔\n25۔ اس نے جواب دیا اور کہا، چاہے وہ گناہ گار ہو یا نہیں، میں نہیں جانتا: ایک بات میں جانتا ہوں، کہ جب میں اندھا تھا، اب میں سمجھتا ہوں۔\n26۔ پھر انہوں نے دوبارہ اس سے کہا، اس نے تم سے کیا کہا؟ اس نے تمہاری آنکھیں کتنی کھول دیں؟\n27۔ اس نے جواب دیا، میں نے تمہیں پہلے ہی بتا دیا ہے، اور تم نے نہیں سنا: تم دوبارہ کیوں سننا چاہتے ہو؟ کیا تم بھی اس کے شاگرد بنو گے؟\n28۔ پھر انہوں نے اسے برا بھلا کہا اور کہا، تم اس کے شاگرد ہو؛ لیکن ہم موسیٰ کے شاگرد ہیں۔\n29۔ ہم جانتے ہیں کہ خدا نے موسیٰ سے بات کی: {جہاں تک} اس {ساتھی} کے بارے میں ہے، ہم نہیں جانتے کہ وہ کہاں سے آیا ہے۔\n30۔ اس آدمی نے جواب دیا اور ان سے کہا، یہاں ایک حیرت انگیز چیز کیوں ہے جو تم نہیں جانتے کہ وہ کہاں سے آیا ہے، اور پھر بھی اس نے میری آنکھیں کھول دی ہیں۔\n31۔ اب ہم جانتے ہیں کہ خدا گناہ گاروں کو نہیں سنتا: لیکن اگر کوئی خدا کا عبادت گزار ہو اور اپنی مرضی پوری کرے، تو وہ سنتا ہے۔\n32. جب سے دنیا شروع ہوئی ہے، کیا یہ نہیں سنا گیا کہ کسی انسان نے نابینا پیدا ہونے والے کی آنکھیں کھولیں۔\n33۔ اگر یہ شخص خدا کا نہ ہوتا تو وہ کچھ نہیں کر سکتا تھا۔\n34۔ انہوں نے جواب دیا اور اس سے کہا، تو تو گناہوں میں پیدا ہوئے ہو، اور کیا تم ہمیں سکھاتے ہو؟ اور انہوں نے اسے نکال دیا۔ {cast...: یا، اسے خارج کر دیا گیا}\n35۔ یسوع نے سنا کہ انہیں نکال دیا گیا ہے؛ اور جب اس نے اسے پایا تو اس سے کہا، کیا تم خدا کے بیٹے پر ایمان رکھتے ہو؟\n36۔ اس نے جواب دیا اور کہا، اے خداوند، وہ کون ہے کہ میں اس پر ایمان لاؤں؟\n37۔ اور یسوع نے اس سے کہا، تو نے اسے دیکھا ہے، اور وہی ہے جو تم سے بات کرتا ہے۔\n38۔ اور اس نے کہا، اے خداوند، میں ایمان رکھتا ہوں۔ اور وہ اس کی عبادت کرتا تھا۔\n39۔ اور یسوع نے کہا، کیونکہ میں اس دنیا میں آیا ہوں، تاکہ جو نہیں دیکھتے وہ دیکھ سکیں؛ اور جو دیکھتے ہیں وہ اندھے ہو جائیں۔\n40۔ اور {کچھ} فریسیوں میں سے جو اس کے ساتھ تھے، نے یہ الفاظ سنے اور اس سے کہا، کیا ہم بھی اندھے ہیں؟\n41۔ یسوع نے ان سے کہا، اگر تم اندھے ہوتے تو تمہیں کوئی گناہ نہ ہوتا؛ لیکن اب تم کہتے ہو، ہم دیکھتے ہیں؛ لہٰذا تمہارا گناہ باقی ہے۔","1. واقعی، یقینا، میں تم سے کہتا ہوں، جو دروازے سے بھیڑ کے چکر میں داخل نہیں ہوتا بلکہ کسی اور راستے سے چڑھتا ہے، وہی چور اور ڈاکو ہے۔\n2۔ لیکن جو دروازے سے داخل ہوتا ہے وہ بھیڑوں کا چرواہا ہے۔\n3۔ دربان اس کے لیے دروازہ کھولتا ہے؛ اور بھیڑ اس کی آواز سنتی ہے: اور وہ اپنی بھیڑوں کو نام سے پکارتا ہے اور انہیں باہر لے جاتا ہے۔\n4۔ اور جب وہ اپنی بھیڑیں نکالتا ہے، تو ان کے سامنے جاتا ہے، اور بھیڑیں اس کے پیچھے چلتی ہیں، کیونکہ وہ اس کی آواز جانتے ہیں۔\n5۔ اور وہ اجنبی کا پیچھا نہیں کریں گے، بلکہ اس سے بھاگ جائیں گے، کیونکہ وہ اجنبیوں کی آواز نہیں جانتے۔\n6۔ یہ تمثیل یسوع نے ان سے کہا: لیکن وہ نہیں سمجھ سکے کہ وہ کیا باتیں ہیں جو اس نے ان سے کہیں۔\n7۔ پھر یسوع نے دوبارہ ان سے کہا، \"واقعی، یقینا، میں تم سے کہتا ہوں، میں بھیڑوں کا دروازہ ہوں۔\n8۔ میرے سامنے جو کچھ بھی آیا وہ چور اور ڈاکو تھے: لیکن بھیڑوں نے انہیں نہیں سنا۔\n9۔ میں دروازہ ہوں: میرے ذریعے اگر کوئی اندر آئے گا تو وہ بچایا جائے گا، اندر جائے گا اور چراگاہ تلاش کرے گا۔\n10۔ چور صرف چوری کرنے، قتل کرنے، اور تباہ کرنے کے لیے آتا ہے: میں آیا ہوں تاکہ انہیں زندگی مل سکے، اور وہ اسے زیادہ مقدار میں حاصل کر سکیں۔\n11۔ میں اچھا چرواہا ہوں: اچھا چرواہا بھیڑوں کے لیے اپنی جان دیتا ہے۔\n12. لیکن جو کرائے کا ہے، اور چرواہا نہیں، جس کی بھیڑیں اپنی نہیں ہیں، وہ بھیڑیا آتا دیکھتا ہے، بھیڑوں کو چھوڑ کر بھاگ جاتا ہے، اور بھیڑیا انہیں پکڑ لیتا ہے اور بھیڑیں بکھیر دیتا ہے۔\n13۔ کرایہ دار بھیڑا، کیونکہ وہ کرائے کا ہے، اور بھیڑوں کی پرواہ نہیں کرتا۔\n14. میں اچھا چرواہا ہوں، اپنی {بھیڑ} کو جانتا ہوں، اور اپنے بارے میں بھی جانا جاتا ہوں۔\n15۔ جیسا کہ باپ مجھے جانتا ہے، ویسے ہی میں باپ کو بھی جانتا ہوں: اور میں بھیڑوں کے لیے اپنی جان دیتا ہوں۔\n16۔ اور میرے پاس اور بھیڑیں ہیں جو اس قبیلے سے نہیں ہیں: انہیں بھی لانا ہے، اور وہ میری آواز سنیں گی؛ اور ایک گدا ہوگا، {اور} ایک چرواہا۔\n17. اسی لیے میرا باپ مجھ سے محبت کرتا ہے، کیونکہ میں اپنی جان قربان کرتا ہوں تاکہ اسے دوبارہ لے سکوں۔\n18۔ کوئی مرد مجھ سے یہ نہیں لیتا، لیکن میں خود ہی اسے چھوڑ دیتا ہوں۔ میرے پاس اسے چھوڑنے کی طاقت ہے، اور دوبارہ لینے کی طاقت ہے۔ یہ حکم مجھے اپنے باپ کی طرف سے ملا ہے۔\n19۔ لہٰذا یہودیوں میں ان اقوال کے لیے پھر تقسیم ہوئی۔\n20۔ اور ان میں سے کئی نے کہا، اس کے پاس شیطان ہے، اور وہ پاگل ہے؛ تم اسے کیوں سنتے ہو؟\n21۔ دوسروں نے کہا، یہ اس کے الفاظ نہیں ہیں جس کے پاس شیطان ہے۔ کیا شیطان نابینا کی آنکھیں کھول سکتا ہے؟\n22۔ اور یروشلم میں وقف کی عید تھی، اور سردی تھی۔\n23۔ اور یسوع سلیمان کے برآمدے میں مندر میں داخل ہوئے۔\n24۔ پھر یہودی اس کے ارد گرد آئے اور اس سے کہا، تم ہمیں کب تک شک میں ڈالتے ہو؟ اگر تم مسیح ہو، تو ہمیں صاف صاف بتاؤ۔ {بنائ...: یا، ہمیں معلق رکھو}\n25۔ میں نے آپ کو بتایا کہ یسوع نے ان کا جواب دیا، اور آپ نے یقین نہیں کیا: جو کام میں اپنے باپ کے نام پر کرتا ہوں، وہ میرے لیے گواہی دیتے ہیں۔\n26۔ لیکن تم ایمان نہیں رکھتے، کیونکہ تم میرے بھیڑوں کے نہیں ہو، جیسا کہ میں نے تم سے کہا۔\n27. میری بھیڑیں میری آواز سنتی ہیں، میں انہیں جانتا ہوں، اور وہ میرے پیچھے چلتی ہیں:\n28۔ اور میں انہیں ابدی زندگی دیتا ہوں؛ اور وہ کبھی ختم نہیں ہوں گے، نہ ہی کوئی {انسان} انہیں میرے ہاتھ سے چھین لے گا۔\n29۔ میرا باپ، جس نے مجھے دیا، سب سے بڑا ہے؛ اور کوئی {انسان} میرے والد کے ہاتھ سے {انہیں} چھین نہیں سکتا۔\n30۔ میں اور {میرا} والد ایک ہیں۔\n31۔ پھر یہودیوں نے دوبارہ پتھر اٹھا کر اسے پتھر مارے۔\n32۔ یسوع نے ان کا جواب دیا، میں نے تمہیں اپنے باپ کی طرف سے بہت نیک کام دکھائے ہیں؛ ان کاموں میں سے کس کے لیے تم مجھے سنگسار کرتے ہو؟\n33۔ یہودیوں نے اس کا جواب دیا، کہا، نیک کام کے لیے ہم تمہیں سنگسار نہیں کرتے؛ لیکن توہین مذہب کے لیے؛ اور کیونکہ تم، مرد ہونے کے ناطے، خود کو خدا بناتے ہو۔\n34۔ یسوع نے ان کا جواب دیا، کیا یہ تمہارے قانون میں نہیں لکھا، میں نے کہا، تم خدا ہو؟\n35۔ اگر اس نے انہیں خدا کہا، جن کے پاس خدا کا کلام آیا، اور صحیفہ توڑا نہیں جا سکتا؛\n36۔ اس کے بارے میں کہیں جسے باپ نے پاک کیا اور دنیا میں بھیجا، تو کفر کرو؛ کیونکہ میں نے کہا، میں خدا کا بیٹا ہوں؟\n37۔ اگر میں اپنے باپ کے کام نہیں کرتا، تو یقین نہ کرو۔\n38۔ لیکن اگر میں یقین کروں، اگرچہ تم مجھ پر یقین نہیں رکھتے، تو اعمال پر ایمان لاؤ: تاکہ تم جان سکو، اور ایمان رکھو، کہ باپ مجھ میں ہے، اور میں اس میں ہوں۔\n39۔ لہٰذا انہوں نے دوبارہ اسے لینے کی کوشش کی، لیکن وہ ان کے ہاتھوں سے بچ نکلا،\n40۔ اور پھر اردن کے پار اس جگہ چلا گیا جہاں جان نے پہلی بار بپتسمہ دیا تھا؛ اور وہیں وہ ٹھہرا۔\n41۔ اور بہت سے لوگ اس کے پاس آئے اور کہا، یوحنا نے کوئی معجزہ نہیں کیا: لیکن جو کچھ جان نے اس شخص کے بارے میں کہا وہ سب سچ تھا۔\n42۔ اور وہاں بہت سے لوگ اس پر ایمان لاتے تھے۔","1۔ اب ایک {آدمی} بیمار تھا، {نام} لازرس، بیت عنیا، مریم کے قصبے اور اس کی بہن مارٹھا کا۔\n2۔ (یہ {وہ} مریم تھی جس نے خداوند کو مرہم سے مسح کیا، اور اس کے پاؤں اپنے بالوں سے صاف کیے، جس کا بھائی لازارس بیمار تھا۔)\n3۔ اسی لیے اس کی بہنوں نے اس کے پاس بھیجا اور کہا، اے خداوند، دیکھو، جس سے تو محبت کرتا ہے وہ بیمار ہے۔\n4۔ جب یسوع نے یہ سنا، تو اس نے کہا، یہ بیماری موت کے لیے نہیں، بلکہ خدا کی جلال کے لیے ہے، تاکہ خدا کے بیٹے کو اس سے جلال ملے۔\n5۔ اب یسوع نے مارتھا، اس کی بہن، اور لعزر سے محبت کی۔\n6۔ جب اسے معلوم ہوا کہ وہ بیمار ہے، تو وہ دو دن اسی جگہ ٹھہرا جہاں وہ تھا۔\n7۔ پھر اس کے بعد وہ اپنے شاگردوں سے کہتا ہے، آؤ دوبارہ یہودیہ میں چلیں۔\n8۔ {اس کے} شاگرد اسے کہتے ہیں، استاد، حالیہ یہودیوں نے تمہیں پتھر مارنے کی کوشش کی؛ اور کیا تم دوبارہ وہاں جاتے ہو؟\n9۔ یسوع نے جواب دیا، کیا دن میں بارہ گھنٹے نہیں ہوتے؟ اگر کوئی دن میں چلتا ہے تو وہ لڑکھڑاتا نہیں، کیونکہ وہ اس دنیا کی روشنی دیکھتا ہے۔\n10۔ لیکن اگر کوئی شخص رات میں چلتا ہے تو وہ لڑکھڑاتا ہے، کیونکہ اس میں روشنی نہیں ہوتی۔\n11۔ یہ باتیں اس نے کہی: اور اس کے بعد وہ ان سے کہتا ہے، ہمارا دوست لازر سو رہا ہے؛ لیکن میں جاتا ہوں، تاکہ اسے نیند سے جگا سکوں۔\n12۔ پھر اس کے شاگردوں نے کہا، خداوند، اگر وہ سوئے گا تو اچھا کرے گا۔\n13۔ اگرچہ یسوع نے اپنی موت کا ذکر کیا: لیکن وہ سمجھتے تھے کہ اس نے نیند میں آرام کرنے کی بات کی ہے۔\n14۔ پھر یسوع نے ان سے صاف کہا، لعزر مر چکا ہے۔\n15۔ اور میں تمہارے لیے خوش ہوں کہ میں وہاں نہیں تھا، جس نیت سے تم یقین کر سکتے ہو؛ پھر بھی، آئیے اس کے پاس چلیں۔\n16۔ پھر تھامس، جسے ڈیڈیمس کہا جاتا ہے، نے اپنے ساتھی شاگردوں سے کہا، آؤ ہم بھی جائیں، تاکہ ہم اس کے ساتھ مر سکیں۔\n17۔ پھر جب یسوع آیا، تو اس نے پایا کہ وہ چار دن پہلے ہی قبر میں لیٹا ہوا ہے۔\n18۔ اب بیت عنیا یروشلم کے قریب تھا، تقریبا پندرہ فرلانگ دور: {تقریبا...: یعنی تقریبا دو میل}\n19۔ اور بہت سے یہودی مارٹھا اور مریم کے پاس آئے تاکہ ان کے بھائی کے بارے میں انہیں تسلی دیں۔\n20۔ پھر مارٹھا، جیسے ہی اسے معلوم ہوا کہ یسوع آ رہا ہے، وہ اس سے ملنے گئی: لیکن مریم گھر میں {ساکت رہی}۔\n21۔ پھر مارٹھا نے یسوع سے کہا، اے خداوند، اگر تم یہاں ہوتے تو میرا بھائی نہ مرتا۔\n22۔ لیکن میں جانتا ہوں کہ اب بھی، جو کچھ بھی تم خدا سے مانگو گے، خدا تمہیں دے گا۔\n23۔ یسوع نے اس سے کہا، تیرا بھائی دوبارہ زندہ ہوگا۔\n24۔ مارٹھا نے اسے کہا، میں جانتی ہوں کہ وہ قیامت میں آخری دن دوبارہ زندہ ہوگا۔\n25۔ یسوع نے اس سے کہا، میں قیامت اور زندگی ہوں: جو مجھ پر ایمان لاتا ہے، چاہے وہ مر چکا ہو، پھر بھی زندہ رہے گا:\n26. اور جو زندہ رہے گا اور مجھ پر ایمان لائے گا وہ کبھی نہیں مرے گا۔ کیا تم اس پر یقین کرتے ہو؟\n27۔ وہ اس سے کہتی ہے، ہاں، خداوند: میں ایمان رکھتی ہوں کہ تو مسیح ہو، خدا کا بیٹا، جو دنیا میں آنا چاہیے۔\n28۔ اور جب اس نے یہ کہا، تو وہ اپنی راہ پر چلی گئی اور چپکے سے مریم کو اپنی بہن کہا، \"مالک آ گیا ہے، اور تمہیں پکار رہا ہے۔\n29۔ جیسے ہی اس نے یہ سنا، وہ فورا اٹھ کھڑی ہوئی اور اس کے پاس آئی۔\n30۔ اب یسوع ابھی شہر میں نہیں آیا تھا، بلکہ اس جگہ پر تھا جہاں مارٹھا اس سے ملی تھی۔\n31۔ یہودی جو اس کے ساتھ گھر میں تھے، اور جب انہوں نے مریم کو دیکھا تو اسے تسلی دی کہ وہ جلدی سے اٹھ کھڑی ہوئی اور باہر نکلی، اس کے پیچھے چلتے ہوئے کہا، وہ وہاں رونے کے لیے قبر پر جاتی ہے۔\n32۔ پھر جب مریم یسوع کے پاس آئی اور اسے دیکھا، تو وہ اس کے قدموں میں گر پڑی اور کہا، اے خداوند، اگر تم یہاں ہوتے تو میرا بھائی نہ مرا۔\n33۔ جب یسوع نے اسے روتے دیکھا، اور یہودیوں کو بھی جو اس کے ساتھ آئے تھے، روتے دیکھا، تو وہ روح میں کراہ اٹھا، اور پریشان ہوا، {پریشان ہوا: Gr. اس نے خود کو تکلیف دی}\n34۔ اور کہا، تم نے اسے کہاں رکھا ہے؟ انہوں نے اس سے کہا، اے خداوند، آؤ اور دیکھو۔\n35۔ یسوع روئے۔\n36۔ پھر یہودیوں نے کہا، دیکھو اس نے اسے کتنا چاہا!\n37۔ اور ان میں سے کچھ نے کہا، کیا یہ آدمی، جس نے اندھوں کی آنکھیں کھولیں، یہ نہیں کر سکتا کہ یہ انسان بھی نہ مرتا؟\n38۔ لہٰذا یسوع پھر اپنے اندر کراہتے ہوئے قبر پر آتا ہے۔ یہ ایک غار تھا، اور اس پر ایک پتھر پڑا تھا۔\n39۔ یسوع نے کہا، تم پتھر ہٹا لو۔ مارٹھا، جو اس کی بہن ہے جو مر چکی ہے، اس سے کہتی ہے، اے خداوند، اس وقت تک وہ بدبو دار ہے: کیونکہ وہ چار دن سے مر چکا ہے۔\n40۔ یسوع نے اس سے کہا، میں نے تم سے نہیں کہا کہ اگر تم ایمان لاؤ تو خدا کی شان دیکھو؟\n41۔ پھر انہوں نے پتھر اس جگہ سے ہٹا لیا جہاں مردہ رکھا گیا تھا۔ اور یسوع نے اپنی آنکھیں اٹھائیں اور کہا، اے باپ، میں تیرا شکر ادا کرتا ہوں کہ تو نے میری بات سنی۔\n42۔ اور میں جانتا تھا کہ تم ہمیشہ میری بات سنتے ہو: لیکن ان لوگوں کی وجہ سے جو کھڑے ہیں، میں نے کہا {یہ} تاکہ وہ یقین کریں کہ تم نے مجھے بھیجا ہے۔\n43۔ اور جب اس نے یہ کہا، تو زور سے پکارا، لازارس، باہر آؤ۔\n44۔ اور جو مردہ تھا وہ باہر آیا، ہاتھ اور پاؤں قبر کے کپڑوں میں بندھے ہوئے، اور اس کا چہرہ رومال سے بندھا ہوا تھا۔ یسوع نے ان سے کہا، اسے چھوڑ دو اور جانے دو۔\n45۔ پھر بہت سے یہودی جو مریم کے پاس آئے اور یسوع کے کیے ہوئے کاموں کو دیکھا، انہوں نے اس پر ایمان لایا۔\n46۔ لیکن ان میں سے کچھ فریسیوں کے پاس گئے اور انہیں بتایا کہ یسوع نے کیا کیا ہے۔\n47۔ پھر سردار کاہنوں اور فریسیوں کو ایک مجلس جمع کیا اور کہا، ہم کیا کریں؟ کیونکہ یہ آدمی بہت سے معجزے کرتا ہے۔\n48۔ اگر ہم اسے اس طرح اکیلا چھوڑ دیں تو تمام {لوگ} اس پر ایمان لائیں گے: اور رومی آئیں گے اور ہماری جگہ اور قوم دونوں کو چھین لیں گے۔\n49۔ اور ان میں سے ایک، {نام} قیافہ، جو اسی سال اعلیٰ کاہن تھا، نے ان سے کہا، تم کچھ نہیں جانتے،\n50۔ اور یہ نہ سمجھیں کہ ہمارے لیے یہ مناسب ہے کہ ایک آدمی عوام کے لیے مرے، اور پوری قوم فنا نہ ہو۔\n51۔ اور اس نے یہ اپنے بارے میں نہیں کہا: لیکن چونکہ وہ اس سال اعلیٰ کاہن تھا، اس نے پیش گوئی کی کہ یسوع اس قوم کے لیے جان دے گا؛\n52۔ اور صرف اس قوم کے لیے نہیں، بلکہ اس لیے بھی کہ وہ خدا کے بچوں کو ایک میں جمع کرے جو باہر بکھرے ہوئے تھے۔\n53۔ پھر اس دن سے انہوں نے مل کر مشورہ کیا کہ اسے موت کے گھاٹ کا سامنا کریں۔\n54۔ لہٰذا یسوع یہودیوں کے درمیان کھلے عام نہیں چلے؛ لیکن وہاں سے وہ ایک علاقے میں گیا، جو افریم نامی شہر میں تھا، اور وہاں اپنے شاگردوں کے ساتھ آگے بڑھا۔\n55۔ اور یہودیوں کا عید فسح قریب آ رہا تھا: اور بہت سے لوگ عید فصح سے پہلے یروشلم چلے گئے تاکہ خود کو پاک کر سکیں۔\n56۔ پھر انہوں نے یسوع کو تلاش کیا، اور مندر میں کھڑے آپس میں بولے، تم کیا سمجھتے ہو کہ وہ عید میں نہیں آئے گا؟\n57۔ اب سردار کاہنوں اور فریسیوں دونوں نے حکم دیا تھا کہ اگر کوئی جانتا ہے کہ وہ کہاں ہے تو وہ دکھائے، تاکہ وہ اسے لے جائے۔","1۔ پھر یسوع فسح سے چھ دن پہلے بیت عنیا آیا، جہاں لازر تھا جو مر چکا تھا، جسے اس نے مردوں میں سے زندہ کیا۔\n2۔ وہاں انہوں نے اس کے لیے رات کا کھانا بنایا؛ اور مارٹھا نے خدمت کی: لیکن لازارس ان میں سے ایک تھا جو اس کے ساتھ میز پر بیٹھا تھا۔\n3۔ پھر اس نے مریم کے لیے ایک پاؤنڈ اسپیکنارڈ کا مرہم لیا، جو بہت مہنگا تھا، اور یسوع کے پاؤں کو مسح کیا، اور اس کے بالوں سے اس کے پاؤں صاف کیے: اور گھر مرہم کی بدبو سے بھر گیا۔\n4۔ پھر اس کے ایک شاگرد، یھودا اسکریوٹی، شمعون کا {بیٹا} کہتا ہے، جو اسے دھوکہ دے گا،\n5. یہ مرہم تین سو پینس میں کیوں نہیں بیچا گیا، اور غریبوں کو کیوں نہیں دیا گیا؟\n6۔ اس نے یہ کہا، یہ نہیں کہ وہ غریبوں کی پرواہ کرتا تھا؛ بلکہ اس لیے کہ وہ چور تھا، اور اس کے پاس تھیلا تھا، اور جو کچھ اس میں رکھا گیا تھا اسے ننگا کر رہا تھا۔\n7۔ پھر یسوع نے کہا، اسے چھوڑ دو: میرے دفن کے دن کے خلاف اس نے یہ بات رکھی ہے۔\n8۔ غریبوں کے لیے جو ہمیشہ تمہارے ساتھ ہوتے ہیں؛ لیکن میں ہمیشہ نہیں رہی۔\n9۔ یہودیوں کے بہت سے لوگ جانتے تھے کہ وہ وہاں موجود ہے: اور وہ صرف یسوع کے لیے نہیں آئے بلکہ اس لیے آئے کہ وہ لازر کو بھی دیکھ سکیں، جسے اس نے مردوں میں سے زندہ کیا تھا۔\n10۔ لیکن سردار کاهنوں نے مشورہ دیا کہ وہ لازر کو بھی قتل کر دیں؛\n11۔ کیونکہ اس کی وجہ سے بہت سے یہودی چلے گئے، اور یسوع پر ایمان لائی۔\n12۔ اگلے دن بہت سے لوگ جو دعوت میں آئے تھے، جب انہوں نے سنا کہ یسوع یروشلم آ رہا ہے،\n13۔ کھجور کے درختوں کی شاخیں لے کر اس سے ملنے نکلا اور پکارا، ہوشعنا: مبارک ہے اسرائیل کا بادشاہ جو خداوند کے نام پر آیا ہے۔\n14۔ اور جب یسوع نے ایک نوجوان گدھا پایا تو اس پر بیٹھ گیا؛ جیسا کہ لکھا گیا ہے،\n15. ڈر مت، سیون کی بیٹی: دیکھو، تیرا بادشاہ آ رہا ہے، گدھے کے گھوڑے پر بیٹھا ہوا۔\n16۔ یہ چیزیں ابتدا میں اس کے شاگردوں کو نہیں سمجھتی تھیں: لیکن جب یسوع کی جلال ہوئی تو انہیں یاد آیا کہ یہ باتیں اس کے بارے میں لکھی گئی تھیں، اور {کہ} انہوں نے یہ سب اس کے ساتھ کیا تھا۔\n17۔ لہٰذا وہ لوگ جو اس کے ساتھ تھے جب اس نے لزرس کو قبر سے بلایا اور مردوں میں سے زندہ کیا، بغیر کسی ریکارڈ کے۔\n18۔ اسی مقصد کے لیے لوگ بھی اس سے ملے، کیونکہ انہوں نے سنا کہ اس نے یہ معجزہ کیا ہے۔\n19۔ لہٰذا فریسیوں نے آپس میں کہا، دیکھو کہ تم کچھ بھی حاصل نہیں کرتے؟ دیکھو، دنیا اس کے پیچھے جا چکی ہے۔\n20۔ اور ان میں کچھ یونانی بھی تھے جو عید میں عبادت کے لیے آئے:\n21۔ یہی بات فلپ کے پاس آئی، جو بیت صیدا آف گلیل کا تھا، اور اس سے دعا کی اور کہا، جناب، ہم یسوع کو دیکھنا چاہتے ہیں۔\n22۔ فلپ آتا ہے اور اینڈریو کو بتاتا ہے: اور پھر اینڈریو اور فلپ یسوع کو بتاتے ہیں۔\n23۔ اور یسوع نے ان کا جواب دیا، کہا، وقت آ گیا ہے کہ انسان کے بیٹے کو جلال دیا جائے۔\n24۔ واقعی، یقینا، میں تم سے کہتا ہوں، جب تک گندم کا دانا زمین میں گرے اور مر نہ جائے، وہ اکیلا رہتا ہے: لیکن اگر مر جائے تو بہت سا پھل دیتا ہے۔\n25۔ جو اپنی زندگی سے محبت کرتا ہے وہ اسے کھو دے گا؛ اور جو اپنی زندگی سے اس دنیا میں نفرت کرتا ہے وہ اسے ہمیشہ کے لیے زندہ رکھے گا۔\n26۔ اگر کوئی میری خدمت کرے تو وہ میرے ساتھ چلے؛ اور جہاں میں ہوں، وہاں میرا خادم بھی ہوگا: اگر کوئی میری خدمت کرے گا، وہی {میرا} باپ عزت کرے گا۔\n27۔ اب میری روح پریشان ہے؛ اور میں کیا کہوں؟ ابا، مجھے اس وقت سے بچاؤ: لیکن اسی مقصد کے لیے میں اس وقت آیا ہوں۔\n28. باپ، اپنے نام کی جلال فرما۔ پھر آسمان سے ایک آواز آئی، {کہی}، میں نے {اسے} کو جلال دیا ہے، اور دوبارہ جلال دوں گا۔\n29۔ لہٰذا وہ لوگ جو کھڑے تھے اور سنے {اسے} نے کہا کہ یہ گرج رہا ہے: دوسروں نے کہا، ایک فرشتہ نے اس سے بات کی۔\n30۔ یسوع نے جواب دیا اور کہا، یہ آواز میرے لیے نہیں بلکہ تمہاری خاطر آئی۔\n31۔ اب اس دنیا کا فیصلہ ہے: اب اس دنیا کا شہزادہ نکال دیا جائے گا۔\n32. اور میں، اگر زمین سے اٹھا جاؤں، تو تمام {انسان} کو اپنی طرف کھینچوں گا۔\n33۔ اس نے یہ کہا، جس سے ظاہر ہوتا ہے کہ اسے کون سی موت مرنی چاہیے۔\n34۔ لوگوں نے اسے جواب دیا، ہم نے شریعت سے سنا ہے کہ مسیح ہمیشہ قائم ہے: اور تم کیسے کہتی ہو، انسان کے بیٹے کو اٹھایا جانا چاہیے؟ یہ انسان کا بیٹا کون ہے؟\n35۔ پھر یسوع نے ان سے کہا، پھر بھی تھوڑی دیر روشنی تمہارے ساتھ ہے۔ جب تک تمہارے پاس روشنی ہے، چلو، ورنہ تم پر اندھیرا چھا جائے گا: کیونکہ جو اندھیرے میں چلتا ہے وہ نہیں جانتا کہ وہ کہاں جا رہا ہے۔\n36۔ جب آپ کے پاس روشنی ہے، تو روشنی پر ایمان لائیں تاکہ آپ روشنی کے بچے بن سکیں۔ یہ باتیں یسوع نے کیں، اور وہ چلا گیا، اور ان سے چھپایا بھی۔\n37۔ اگرچہ اس نے ان سے پہلے بہت سے معجزے کیے تھے، پھر بھی انہوں نے اس پر ایمان نہیں لایا:\n38۔ تاکہ اشیاس نبی کا کلام پورا ہو جائے، جو اس نے کہا، اے خداوند، کس نے ہماری خبر پر یقین کیا؟ اور خداوند کا بازو کس کے لیے ظاہر ہوا ہے؟\n39۔ اس لیے وہ یقین نہ کر سکے، کیونکہ عیسیٰ نے پھر کہا،\n40۔ اس نے ان کی آنکھیں اندھا کر دی ہیں، اور ان کے دل کو سخت کر دیا ہے؛ کہ وہ {اپنی} آنکھوں سے نہ دیکھیں، نہ اپنے دل سے سمجھیں، اور تبدیل ہو جائیں، اور میں انہیں شفا دوں۔\n41۔ یہ باتیں یسیاس نے کہیں، جب اس نے اپنی شان دیکھی اور اس کے بارے میں کہا۔\n42۔ تاہم، اہم حکمرانوں میں بھی بہت سے لوگ اس پر یقین رکھتے تھے؛ لیکن فریسیوں کی وجہ سے انہوں نے اس کا اعتراف نہیں کیا، ورنہ انہیں عبادت گاہ سے نکال دیا جاتا:\n43۔ کیونکہ وہ لوگوں کی تعریف کو خدا کی تعریف سے زیادہ پسند کرتے تھے۔\n44۔ یسوع نے پکار کر کہا، جو مجھ پر ایمان رکھتا ہے، وہ مجھ پر نہیں بلکہ اس پر ایمان رکھتا ہے جس نے مجھے بھیجا۔\n45۔ اور جو مجھے دیکھتا ہے، وہی دیکھتا ہے جس نے مجھے بھیجا۔\n46. میں دنیا میں روشنی آیا ہوں، تاکہ جو بھی مجھ پر ایمان لائے وہ اندھیرے میں نہ رہے۔\n47۔ اور اگر کوئی میرے الفاظ سنے، اور یقین نہ کرے، تو میں اس کا فیصلہ نہیں کرتا: کیونکہ میں دنیا کا فیصلہ کرنے نہیں آیا بلکہ دنیا کو بچانے آیا ہوں۔\n48۔ جو مجھے رد کرتا ہے، اور میرے الفاظ قبول نہیں کرتا، اس کا فیصلہ کرنے والا ہے: جو کلام میں نے کہا ہے، وہی اسے آخری دن میں فیصلہ کرے گا۔\n49۔ کیونکہ میں نے اپنے بارے میں بات نہیں کی؛ لیکن جس باپ نے مجھے بھیجا، اس نے مجھے حکم دیا کہ مجھے کیا کہنا ہے اور کیا کہنا ہے۔\n50۔ اور میں جانتا ہوں کہ اس کا حکم زندگی دائمی ہے: جو کچھ بھی میں بولوں، جیسے باپ نے مجھ سے کہا، میں بھی بولتا ہوں۔","1۔ اب عید فصح سے پہلے، جب یسوع کو معلوم ہوا کہ اس کا وقت آ گیا ہے کہ وہ اس دنیا سے باپ کی طرف روانہ ہو جائے، اور اپنے لوگوں سے جو دنیا میں تھے ان سے محبت کی، اس نے انہیں آخر تک محبت کی۔\n2۔ اور رات کا کھانا ختم ہو گیا، شیطان نے اب یھودا اسکریوطی، شمعون کے {بیٹے} کے دل میں اسے دھوکہ دینے کے لیے داخل کر دیا تھا؛\n3۔ یسوع جانتے ہوئے کہ باپ نے سب کچھ اس کے ہاتھوں میں دے دیا ہے، اور وہ خدا کی طرف سے آیا ہے اور خدا کے پاس گیا؛\n4۔ وہ رات کے کھانے سے اٹھتا ہے، اور اپنے کپڑے اتار دیتا ہے؛ اور تولیہ لیا اور خود کو تیار کیا۔\n5۔ اس کے بعد اس نے پانی ایک حوض میں ڈالا، اور شاگردوں کے پاؤں دھونا شروع کیا، اور تولیے سے انہیں صاف کیا جس سے وہ بندھا ہوا تھا۔\n6۔ پھر وہ شمعون پطرس کے پاس آتا ہے: اور پطرس اس سے کہتا ہے، اے خداوند، کیا تو میرے پاؤں دھوتا ہے؟ {پیٹر کہتا ہے: گری۔ وہ کہتا ہے}\n7۔ یسوع نے جواب دیا اور کہا، جو میں کرتا ہوں وہ تم اب نہیں جانتے؛ لیکن تم بعد میں جان جاؤ گے۔\n8۔ پیٹر اسے کہتا ہے، تو میرے پاؤں کبھی نہ دھوؤ۔ یسوع نے جواب دیا، اگر میں تمہیں نہ دھوؤں تو تمہارا میرے ساتھ کوئی حصہ نہیں۔\n9۔ شمعون پطرس نے اسے فرمایا، اے خداوند، صرف میرے پاؤں نہیں، بلکہ {میرے} ہاتھ اور {میرا} سر بھی۔\n10۔ یسوع اسے کہتے ہیں، جو دھویا گیا ہے اسے صرف اپنے پاؤں دھونے کی ضرورت ہے، بلکہ ہر تھوڑا پاک ہے: اور تم پاک ہو، لیکن سب نہیں۔\n11۔ کیونکہ وہ جانتا تھا کہ کون اسے دھوکہ دے گا؛ اس لیے اس نے کہا، تم سب پاک نہیں ہو۔\n12۔ تو جب اس نے ان کے پاؤں دھوئے، اپنے کپڑے اتار دیے، اور دوبارہ اتارا تو اس نے ان سے کہا، کیا تم جانتے ہو کہ میں نے تمہارے ساتھ کیا کیا ہے؟\n13. تم مجھے مالک اور رب کہتے ہو: اور تم اچھا کہتے ہو؛ کیونکہ {تو} میں ہوں۔\n14۔ اگر میں، آپ کے رب اور آقا، آپ کے پاؤں دھو چکا ہوں؛ تم دونوں کو ایک دوسرے کے پاؤں دھونے چاہئیں۔\n15۔ کیونکہ میں نے تمہیں ایک مثال دی ہے کہ تم ویسا ہی کرو جیسا میں نے تمہارے ساتھ کیا۔\n16. واقعی، یقینا، میں تم سے کہتا ہوں، خادم اپنے رب سے بڑا نہیں؛ نہ ہی وہ جو بھیجا گیا ہے اس سے عظیم جس نے اسے بھیجا۔\n17۔ اگر آپ یہ باتیں جانتے ہیں تو خوش آمدید اگر آپ انہیں کریں۔\n18۔ میں تم سب کے بارے میں بات نہیں کرتا: میں جانتا ہوں کہ میں نے کس کو چنا ہے، بلکہ تاکہ کتاب مقدس پوری ہو، جو میرے ساتھ روٹی کھاتا ہے اس نے میرے خلاف اپنی ایڑی اٹھائی ہے۔\n19۔ اب میں تمہیں بتاتا ہوں اس سے پہلے کہ وہ آئے، کہ جب وہ ہو جائے تو تم یقین کر لو کہ میں {وہ} ہوں۔ {اب: یا، آئندہ سے}\n20. واقعی، یقینا، میں تم سے کہتا ہوں، جو جسے میں بھیجتا ہوں اسے قبول کرتا ہے؛ اور جو مجھے قبول کرتا ہے، وہی قبول کرتا ہے جس نے مجھے بھیجا۔\n21۔ جب یسوع نے یہ کہا، تو وہ روحانی طور پر پریشان ہوا، گواہی دی اور کہا، واقعی، یقینا، میں تم سے کہتا ہوں کہ تم میں سے کوئی مجھے دھوکہ دے گا۔\n22۔ پھر شاگرد ایک دوسرے کی طرف دیکھنے لگے، اس بات پر شک کرنے لگے کہ وہ کس سے بات کر رہا ہے۔\n23۔ اب یسوع کے سینے پر اس کے ایک شاگرد کا سہارا لگا ہوا تھا، جس سے یسوع محبت کرتا تھا۔\n24۔ اس لیے شمعون پیٹر نے اسے اشارہ کیا کہ وہ پوچھے کہ وہ کس کے بارے میں بات کر رہا ہے۔\n25۔ پھر وہ یسوع کے سینے پر لیٹا ہوا ہے اور اس سے کہتا ہے، اے خداوند، کون ہے؟\n26۔ یسوع نے جواب دیا، 'وہی ہے، جسے میں ایک گھونٹ دوں گا، جب میں اسے ڈبوؤں گا۔ اور جب اس نے سوپ پی لیا، تو اس نے یہودا اسخریوطی کو دے دیا، جو شمعون کا بیٹا تھا۔ {sop: یا، ٹکڑا}\n27۔ اور سوپ کے بعد شیطان اس میں داخل ہوا۔ پھر یسوع نے اس سے کہا، کہ تم کرو، جلدی کرو۔\n28۔ اب میز پر موجود کوئی آدمی نہیں جانتا تھا کہ اس نے یہ بات کس نیت سے کہی ہے۔\n29۔ کیونکہ ان میں سے کچھ نے سوچا، کیونکہ یہوداہ کے پاس تھیلا تھا، کہ یسوع نے اسے کہا تھا، \"وہ چیزیں خرید لو جن کی ہمیں عید کے خلاف ضرورت ہے؛ یا، کہ اسے غریبوں کو کچھ دینا چاہیے۔\n30۔ پھر جب وہ سوپ وصول کر چکا تھا، فورا باہر چلا گیا: اور رات ہو گئی۔\n31۔ لہٰذا، جب وہ باہر نکلا، یسوع نے کہا، اب انسان کا بیٹا جلال پایا گیا ہے، اور خدا اس میں جلال پاتا ہے۔\n32۔ اگر خدا اس میں جلال پائے، تو خدا بھی اپنے اندر اس کی تمجید کرے گا، اور فورا اس کی جلال کرے گا۔\n33۔ چھوٹے بچے، پھر بھی میں تمہارے ساتھ تھوڑا وقت گزارتا ہوں۔ تم مجھے تلاش کرو گے: اور جیسا کہ میں نے یہودیوں سے کہا، جہاں میں جاؤں تم نہیں آؤ گے؛ تو اب میں تم سے کہتا ہوں۔\n34۔ میں تمہیں ایک نیا حکم دیتا ہوں، کہ تم ایک دوسرے سے محبت کرو؛ جیسے میں نے تم سے محبت کی ہے، کہ تم بھی ایک دوسرے سے محبت کرتے ہو۔\n35۔ اس سے تمام لوگ جان لیں گے کہ تم میرے شاگرد ہو، اگر تم ایک دوسرے سے محبت کرو۔\n36۔ شمعون پطرس نے اس سے کہا، اے خداوند، کہاں جا رہے ہو؟ یسوع نے جواب دیا، جہاں میں جاؤں، تم اب میرا پیچھا نہیں کر سکتے؛ لیکن تم بعد میں میرے پیچھے آؤ گے۔\n37۔ پطرس نے اس سے کہا، خداوند، میں اب تیرے پیچھے کیوں نہیں چل سکتا؟ میں تمہارے لیے اپنی جان قربان کروں گا۔\n38۔ یسوع نے اسے جواب دیا، کیا تم میری خاطر اپنی جان قربان کرو گے؟ یقینا، واقعی، میں تم سے کہتا ہوں، مرغ کبھی بانگ نہیں کرے گا، جب تک تم مجھے تین بار انکار نہ کرو۔","1۔ اپنے دل کو پریشان نہ ہونے دو: تم خدا پر ایمان رکھتے ہو، مجھ پر بھی ایمان رکھو۔\n2۔ میرے والد کے گھر میں کئی حویلیاں ہیں: اگر {ایسا نہ ہوتا} تو میں تمہیں بتا دیتا۔ میں تمہارے لیے جگہ تیار کرنے گیا ہوں۔\n3۔ اور اگر میں جا کر تمہارے لیے جگہ تیار کروں گا، تو میں دوبارہ آؤں گا اور تمہیں اپنے لیے قبول کروں گا؛ کہ جہاں میں ہوں، {وہاں} تم بھی ہو سکتے ہو۔\n4. اور جہاں میں جاتا ہوں، تم جانتے ہو، اور جس طرح تم جانتے ہو۔\n5۔ تھامس نے اسے کہا، اے خداوند، ہم نہیں جانتے کہ تم کہاں جا رہے ہو؛ اور ہم راستہ کیسے جان سکتے ہیں؟\n6۔ یسوع اس سے فرماتا ہے، میں راستہ، سچائی اور زندگی ہوں: کوئی انسان باپ کے پاس نہیں آتا، سوائے میرے ذریعے۔\n7۔ اگر تم مجھے جانتے تو میرے باپ کو بھی جانتے ہوتے: اور اب سے تم اسے جانتے اور دیکھتے ہو۔\n8۔ فلپ اسے کہتا ہے، خداوند، ہمیں باپ دکھاؤ، اور یہ ہمیں کافی ہے۔\n9۔ یسوع اس سے کہتا ہے، کیا میں تمہارے ساتھ اتنا وقت گزار چکا ہوں، اور پھر بھی تم نے مجھے نہیں جانا، فلپ؟ جس نے مجھے دیکھا ہے اس نے باپ کو دیکھا ہے؛ اور پھر، آپ ہمیں باپ دکھاتے ہیں، کیا کہتے ہیں؟\n10۔ کیا تم یقین نہیں رکھتے کہ میں باپ میں ہوں، اور باپ میرے اندر ہے؟ جو الفاظ میں تم سے کہتا ہوں وہ میں اپنے بارے میں نہیں کہتا: بلکہ وہ باپ جو میرے اندر بسا ہے، وہ کام کرتا ہے۔\n11۔ یقین کرو کہ میں باپ میں ہوں، اور باپ میرے اندر ہے: ورنہ صرف اعمال کے لیے مجھ پر یقین کرو۔\n12۔ واقعی، یقینا، میں تم سے کہتا ہوں، جو مجھ پر ایمان لائے گا، جو میں کرتا ہوں وہ بھی کرے گا؛ اور وہ ان سے بھی بڑے کام کرے گا؛ کیونکہ میں اپنے والد کے پاس جاتا ہوں۔\n13۔ اور جو کچھ تم میرے نام پر مانگو گے، وہ میں کروں گا، تاکہ باپ بیٹے میں جلال پایا جائے۔\n14۔ اگر تم میرے نام پر کچھ مانگو گے تو میں کروں گا۔\n15۔ اگر تم مجھ سے محبت کرتے ہو تو میرے احکامات کی پیروی کرو۔\n16۔ اور میں باپ سے دعا کروں گا، اور وہ تمہیں ایک اور تسلی دینے والا دے گا، تاکہ وہ ہمیشہ تمہارے ساتھ رہے؛\n17۔ {حتی} سچائی کی روح؛ جسے دنیا قبول نہیں کر سکتی، کیونکہ وہ اسے نہیں دیکھتی، نہ جانتی ہے: لیکن تم اسے جانتے ہو؛ کیونکہ وہ تمہارے ساتھ رہتا ہے، اور تمہارے اندر ہوگا۔\n18۔ میں تمہیں بے آرام نہیں چھوڑوں گا: میں تمہارے پاس آؤں گا۔ {بے آرام: یا، یتیم}\n19۔ پھر بھی تھوڑی دیر بعد، اور دنیا مجھے مزید نہیں دیکھتی؛ لیکن تم مجھے دیکھتے ہو: کیونکہ میں زندہ ہوں، تم بھی زندہ رہو گے۔\n20۔ اس دن تم جان لو گے کہ میں اپنے باپ میں ہوں، اور تم مجھ میں ہو، اور میں تم میں ہوں۔\n21۔ جو میرے احکامات رکھتا ہے اور ان پر عمل کرتا ہے، وہی مجھ سے محبت کرتا ہے: اور جو مجھ سے محبت کرے گا وہ میرے باپ سے محبت کرے گا، اور میں اس سے محبت کروں گا اور اس کے سامنے ظاہر ہوں گا۔\n22۔ یھودا نے اس سے کہا، نہ کہ اسخریوط، اے خداوند، کہ کیسے ممکن ہے کہ تم اپنے آپ کو ہمارے سامنے ظاہر کرو گے، نہ کہ دنیا کے سامنے نہیں؟\n23۔ یسوع نے جواب دیا اور کہا، اگر کوئی آدمی مجھ سے محبت کرے گا تو وہ میرے الفاظ پر قائم رہے گا: اور میرا باپ اسے محبت کرے گا، اور ہم اس کے پاس آئیں گے اور اس کے ساتھ قیام کریں گے۔\n24۔ جو مجھ سے محبت نہیں کرتا وہ میری باتیں نہیں مانتا: اور جو کلام تم سنتے ہو وہ میرا نہیں بلکہ اس باپ کا ہے جس نے مجھے بھیجا۔\n25۔ یہ باتیں میں نے تم سے کہی ہیں، اور پھر بھی تمہارے ساتھ موجود ہوں۔\n26۔ لیکن تسلی دینے والا، {جو ہے} روح القدس، جسے باپ میرے نام پر بھیجے گا، وہ تمہیں سب کچھ سکھائے گا، اور جو کچھ بھی میں نے تمہیں کہا ہے وہ سب یاد دلائے گا۔\n27. میں آپ کے ساتھ امن چھوڑتا ہوں، اپنا امن آپ کو دیتا ہوں: جیسے دنیا دیتی ہے، میں آپ کو دیتا ہوں۔ اپنے دل کو پریشان نہ کرے، نہ ہی اسے ڈرنے دو۔\n28۔ تم نے سنا کہ میں نے تم سے کہا، میں چلا جاتا ہوں، اور پھر تمہارے پاس آتا ہوں۔ اگر تم مجھ سے محبت کرتے، تو خوش ہوتے، کیونکہ میں نے کہا، میں باپ کے پاس جاتا ہوں: کیونکہ میرا باپ مجھ سے بڑا ہے۔\n29۔ اور اب میں نے تمہیں اس سے پہلے بتایا ہے کہ جب یہ ہو جائے تو تم یقین کر سکتے ہو۔\n30۔ آئندہ میں تم سے زیادہ بات نہیں کروں گا: کیونکہ اس دنیا کا شہزادہ آتا ہے، اور میرے اندر کچھ نہیں۔\n31۔ بلکہ تاکہ دنیا جان سکے کہ میں باپ سے محبت کرتا ہوں؛ اور جیسا کہ باپ نے مجھے حکم دیا، میں بھی حکم دیتا ہوں۔ اٹھو، چلو یہاں سے چلتے ہیں۔","1۔ میں سچا بیل ہوں، اور میرا باپ کسان ہے۔\n2۔ میرے اندر کی ہر شاخ جو پھل نہیں دیتی، وہ ہٹا دیتا ہے؛ اور جو بھی پھل دیتی ہے، وہ اسے صاف کرتا ہے تاکہ وہ زیادہ پھل دے سکے۔\n3۔ اب تم اس کلام کے ذریعے پاک ہو جو میں نے تم سے کہا ہے۔\n4۔ میرے اندر رہو، اور میں تم میں۔ جیسے شاخ خود سے پھل نہیں دے سکتی، سوائے اس کے کہ وہ بیل میں رہتی ہے؛ تم مزید نہیں کر سکتے، سوائے اس کے کہ تم میرے اندر رہو۔\n5۔ میں بیل ہوں، تم شاخیں ہو: جو میرے اندر رہتا ہے، اور میں اس میں رہتا ہوں، وہ بھی بہت سا پھل دیتا ہے: کیونکہ میرے بغیر تم کچھ نہیں کر سکتے۔ {میرے بغیر: یا، مجھ سے کٹا ہوا}\n6۔ اگر کوئی آدمی میرے اندر نہ رہے، تو وہ شاخ کی طرح پھینک دیا جاتا ہے اور مرجھا جاتا ہے؛ اور لوگ انہیں جمع کرتے ہیں، اور آگ میں پھینک دیتے ہیں، اور وہ جل جاتے ہیں۔\n7۔ اگر تم میرے اندر رہو اور میرے الفاظ تم میں رہیں، تو تم جو چاہو مانگو گے، اور وہ تمہارے ساتھ ہوگا۔\n8۔ یہاں میرے باپ کی جلال ہے، کہ تم بہت پھل دیتے ہو؛ تو تم میرے شاگرد بنو گے۔\n9۔ جیسے باپ نے مجھ سے محبت کی ہے، ویسے ہی میں نے تم سے محبت کی ہے: میری محبت میں جاری رکھو۔\n10۔ اگر تم میرے احکامات پر عمل کرو گے تو میری محبت میں رہو گے؛ جیسے میں نے اپنے باپ کے احکامات پورے کیے ہیں، اور اس کی محبت میں قائم ہوں۔\n11۔ یہ باتیں میں نے تم سے کہی ہیں، تاکہ میری خوشی تم میں رہے، اور تمہاری خوشی مکمل ہو۔\n12. یہ میرا حکم ہے، کہ تم ایک دوسرے سے محبت کرو، جیسے میں نے تم سے محبت کی ہے۔\n13۔ اس سے بڑی محبت کوئی انسان نہیں کہ انسان اپنے دوستوں کے لیے اپنی جان قربان کرے۔\n14. تم میرے دوست ہو، اگر تم جو بھی میں حکم دوں وہ کرو۔\n15۔ اب سے میں آپ کو خادم نہیں کہتا؛ کیونکہ خادم نہیں جانتا کہ اس کا رب کیا کرتا ہے: لیکن میں نے تمہیں دوست کہا ہے؛ جو کچھ میں نے اپنے والد کے بارے میں سنا ہے، اس کے لیے میں نے تمہیں بتایا ہے۔\n16۔ تم نے مجھے نہیں چنا، بلکہ میں نے تمہیں چنا ہے، اور تمہیں مقرر کیا ہے کہ تم جا کر پھل لاؤ، اور تمہارا پھل باقی رہے: تاکہ جو کچھ تم میرے نام پر باپ سے مانگو، وہ تمہیں دے سکے۔\n17. یہ چیزیں میں تمہیں حکم دیتا ہوں کہ تم ایک دوسرے سے محبت کرو۔\n18۔ اگر دنیا تم سے نفرت کرتی ہے، تو تم جانتے ہو کہ اس نے مجھ سے پہلے نفرت کی تھی۔\n19۔ اگر تم دنیا کے ہوتے، تو دنیا اپنے لوگوں سے محبت کرتی: لیکن کیونکہ تم دنیا سے نہیں ہو، بلکہ میں نے تمہیں دنیا سے چنا ہے، اس لیے دنیا تم سے نفرت کرتی ہے۔\n20۔ وہ لفظ یاد رکھو جو میں نے تم سے کہا تھا، خادم اپنے رب سے بڑا نہیں۔ اگر انہوں نے مجھے ستایا ہے، تو وہ تمہیں بھی ستائیں گے؛ اگر انہوں نے میری بات پر عمل کیا ہے، تو وہ آپ کی بھی بات پر عمل کریں گے۔\n21. لیکن یہ سب کچھ وہ تمہارے ساتھ میرے نام کے لیے کریں گے، کیونکہ وہ اسے نہیں جانتے جس نے مجھے بھیجا۔\n22۔ اگر میں نہ آ کر ان سے بات کرتا تو انہیں گناہ نہ ہوتا؛ لیکن اب ان کے گناہ کے لیے کوئی چادر نہیں۔ {کلوک: یا، بہانہ}\n23۔ جو مجھ سے نفرت کرتا ہے وہ میرے باپ سے بھی نفرت کرتا ہے۔\n24۔ اگر میں نے ان میں وہ کام نہ کیے ہوتے جو کسی اور انسان نے نہیں کیے، تو انہیں گناہ نہ ہوتا: لیکن اب انہوں نے مجھے اور میرے باپ دونوں کو دیکھا اور نفرت کی۔\n25. لیکن {یہ ہو گیا}، تاکہ ان کے قانون میں لکھا ہوا کلام پورا ہو جائے، انہوں نے مجھے بغیر وجہ کے نفرت کی۔\n26۔ لیکن جب تسلی دینے والا آئے گا، جسے میں باپ کی طرف سے آپ کے پاس بھیجوں گا، {حتیٰ کہ} سچائی کی روح بھی، جو باپ سے نکلتی ہے، تو وہ میرے بارے میں گواہی دے گا:\n27۔ اور تم بھی گواہی دو گے، کیونکہ تم شروع سے میرے ساتھ رہے ہو۔","1۔ یہ باتیں میں نے تم سے کہی ہیں کہ تمہیں برا نہ لگے۔ {ناراض: شرمندہ یا، لڑکھڑانے پر مجبور کیا}\n2۔ وہ تمہیں عبادت گاہوں سے نکال دیں گے: ہاں، وقت آتا ہے کہ جو تمہیں مارے گا وہ سمجھے گا کہ وہ خدا کی خدمت کر رہا ہے۔\n3۔ اور یہ سب وہ تمہارے ساتھ کریں گے، کیونکہ انہوں نے نہ باپ کو جانا ہے، نہ مجھے۔\n4۔ لیکن یہ باتیں میں نے تمہیں بتائی ہیں، تاکہ جب وقت آئے تو تم یاد رکھو کہ میں نے تمہیں ان کے بارے میں بتایا تھا۔ اور یہ باتیں میں نے شروع میں تم سے نہیں کہیں، کیونکہ میں تمہارے ساتھ تھا۔\n5. لیکن اب میں اس کے پاس جا رہا ہوں جس نے مجھے بھیجا؛ اور تم میں سے کوئی مجھ سے نہیں پوچھتا، کہاں جا رہے ہو؟\n6۔ لیکن چونکہ میں نے یہ باتیں تم سے کہی ہیں، تمہارے دل میں غم بھر گیا ہے۔\n7. پھر بھی میں آپ کو سچ بتاتا ہوں؛ یہ تمہارے لیے بہتر ہے کہ میں چلا جاؤں: کیونکہ اگر میں نہ جاؤں تو تسلی دینے والا تمہارے پاس نہیں آئے گا؛ لیکن اگر میں چلا گیا تو اسے تمہارے پاس بھیج دوں گا۔\n8۔ اور جب وہ آئے گا، تو وہ گناہ، راستبازی اور انصاف کی دنیا کو ملامت کرے گا: {ملامت کرو: یا، قائل کرو}\n9۔ گناہ کا، کیونکہ وہ مجھ پر ایمان نہیں رکھتے؛\n10۔ راستبازی کی، کیونکہ میں اپنے باپ کے پاس جاتا ہوں، اور تم مجھے دوبارہ نہیں دیکھتے؛\n11۔ فیصلے کی، کیونکہ اس دنیا کے شہزادے کا فیصلہ کیا جاتا ہے۔\n12. میرے پاس تم سے کہنے کو ابھی بہت کچھ ہے، لیکن تم اب برداشت نہیں کر سکتے۔\n13۔ تاہم جب وہ، سچائی کا روح، آئے گا، تو وہ تمہیں تمام سچائی کی طرف لے جائے گا: کیونکہ وہ اپنے بارے میں بات نہیں کرے گا؛ لیکن جو کچھ وہ سنے گا، وہی بولے گا: اور وہ تمہیں آنے والے واقعات دکھائے گا۔\n14۔ وہ میری جلال کرے گا: کیونکہ وہ میرا جلال حاصل کرے گا، اور تمہیں دکھائے گا۔\n15۔ جو کچھ باپ کے پاس ہے وہ سب میری ہے: اس لیے میں نے کہا کہ وہ میرے میں سے لے گا اور تمہیں دکھائے گا۔\n16. تھوڑی دیر کے لیے، اور تم مجھے نہیں دیکھو گے: اور پھر، تھوڑی دیر کے لیے، اور تم مجھے دیکھو گے، کیونکہ میں باپ کے پاس جاتا ہوں۔\n17۔ پھر اس کے کچھ شاگردوں نے آپس میں کہا، یہ کیا ہے جو وہ ہم سے کہتا ہے، تھوڑی دیر کے لیے، اور تم مجھے نہیں دیکھو گے؛ اور پھر، تھوڑی دیر کے لیے، اور تم مجھے دیکھو گے: اور کیونکہ میں باپ کے پاس جاتا ہوں؟\n18۔ لہٰذا انہوں نے کہا، یہ کیا ہے جو اس نے کہا، تھوڑی دیر کے لیے؟ ہم نہیں بتا سکتے کہ اس نے کیا کہا۔\n19۔ اب یسوع جان گیا کہ وہ اس سے پوچھنا چاہتے ہیں، اور اس نے ان سے کہا، کیا تم آپس میں اس بات کے بارے میں پوچھو گے جو میں نے کہا، تھوڑی دیر کے لیے، اور تم مجھے نہیں دیکھو گے: اور پھر تھوڑی دیر کے لیے، پھر تم مجھے دیکھو گے؟\n20۔ واقعی، یقینا، میں تم سے کہتا ہوں، کہ تم روؤ گے اور ماتم کرو گے، لیکن دنیا خوش ہوگی: اور تم غمگین ہو گے، لیکن تمہارا غم خوشی میں بدل جائے گا۔\n21۔ عورت جب مصیبت میں ہوتی ہے تو غمگین ہوتی ہے، کیونکہ اس کا وقت آ چکا ہے: لیکن جیسے ہی وہ بچے سے پیدا ہوتی ہے، وہ مزید اس اذیت کو یاد نہیں رکھتی، خوشی کے لیے کہ ایک مرد دنیا میں پیدا ہوا ہے۔\n22۔ اور اب تم غمگین ہو: لیکن میں تمہیں دوبارہ دیکھوں گا، اور تمہارا دل خوش ہوگا، اور تمہاری خوشی کوئی تم سے نہیں چھین سکتا۔\n23۔ اور اس دن تم مجھ سے کچھ نہیں پوچھو گے۔ یقینا، واقعی، میں تم سے کہتا ہوں، جو کچھ بھی تم میرے نام کے لیے باپ سے مانگو گے، وہ تمہیں دے گا۔\n24۔ اب تک تم نے میرے نام پر کچھ نہیں مانگا: مانگو، اور تمہیں مل جائے گا، تاکہ تمہاری خوشی پوری ہو۔\n25۔ یہ باتیں میں نے تم سے امثال میں کہی ہیں: لیکن وقت آتا ہے جب میں تم سے امثال میں بات نہیں کروں گا، بلکہ تمہیں باپ کے بارے میں صاف دکھاؤں گا۔ {کہاوتیں: یا، تمثیلات}\n26۔ اس دن تم میرے نام پر دعا کرو گے: اور میں تم سے یہ نہیں کہتا کہ میں تمہارے لیے باپ سے دعا کروں گا:\n27۔ کیونکہ خود باپ تم سے محبت کرتا ہے، کیونکہ تم نے مجھ سے محبت کی اور ایمان لیا کہ میں خدا سے باہر آیا ہوں۔\n28۔ میں باپ سے نکلا ہوں، اور دنیا میں آیا ہوں: پھر میں دنیا چھوڑ کر باپ کے پاس جاتا ہوں۔\n29۔ اس کے شاگردوں نے اس سے کہا، دیکھو، اب تو صاف صاف بولو اور کوئی کہاوت نہیں بولتا۔ {کہاوت: یا، تمثیل}\n30۔ اب ہمیں یقین ہے کہ تم سب کچھ جانتے ہو، اور کسی کو تم سے پوچھنے کی ضرورت نہیں: اسی وجہ سے ہم ایمان رکھتے ہیں کہ تم خدا سے نکلا ہو۔\n31۔ یسوع نے ان کا جواب دیا، کیا تم اب ایمان لاتے ہو؟\n32۔ دیکھو، وہ وقت آ رہا ہے، ہاں، اب آ چکا ہے، کہ تم بکھر جاؤ گے، ہر آدمی اپنے لیے ہو جائے گا، اور مجھے اکیلا چھوڑ دو گے: اور پھر بھی میں اکیلا نہیں ہوں، کیونکہ باپ میرے ساتھ ہے۔ {اس کا اپنا: یا، اپنا گھر}\n33۔ یہ باتیں میں نے تم سے کہی ہیں، تاکہ تم مجھ میں سکون پا سکو۔ دنیا میں تمہیں مصیبت آئے گی: لیکن خوش رہو؛ میں نے دنیا پر قابو پا لیا ہے۔","1۔ یہ الفاظ یسوع نے کہا، اور اپنی آنکھیں آسمان کی طرف اٹھا کر کہا، باپ، وقت آ گیا ہے؛ اپنے بیٹے کی جلال کرو، تاکہ تمہارا بیٹا بھی تمہیں جلال دے:\n2۔ جیسے تم نے اسے تمام جسموں پر اختیار دیا ہے، تاکہ وہ اتنے لوگوں کو ابدی زندگی دے جو تم نے اسے دی ہے۔\n3۔ اور یہ ابدی زندگی ہے، تاکہ وہ تمہیں جان سکیں جو واحد سچا خدا ہے، اور یسوع مسیح کو، جسے تم نے بھیجا ہے۔\n4۔ میں نے زمین پر تمہیں جلال بخشا: میں نے وہ کام مکمل کیا جو تم نے مجھے کرنے کے لیے دیا۔\n5. اور اب، اے باپ، اپنی ذات سے مجھے جلال بخش، اس جلال کے ساتھ جو میں نے دنیا کے وجود سے پہلے تیرے ساتھ حاصل کیا تھا۔\n6۔ میں نے تیرا نام ان لوگوں کے سامنے ظاہر کیا ہے جنہیں تو نے مجھے دنیا سے نکالا: وہ تمہارے تھے، اور تو نے انہیں مجھے دیا؛ اور انہوں نے تمہارا وعدہ پورا کیا۔\n7۔ اب وہ جان چکے ہیں کہ جو کچھ بھی تم نے مجھے دیا ہے وہ سب تمہاری طرف سے ہے۔\n8۔ کیونکہ میں نے انہیں وہ الفاظ دیے جو تم نے مجھے دیے؛ اور انہوں نے خود کو قبول کر لیا ہے، اور یقینا جانتے ہیں کہ میں تم سے نکلا ہوں، اور انہوں نے یقین کیا کہ تم نے مجھے بھیجا ہے۔\n9۔ میں ان کے لیے دعا کرتا ہوں: میں دنیا کے لیے نہیں، بلکہ ان کے لیے دعا کرتا ہوں جو تم نے مجھے دیے ہیں؛ کیونکہ وہ تمہارے ہیں۔\n10۔ اور میرے سب تمہارے ہیں، اور تمہارے میرے ہیں؛ اور میں ان میں جلال پاتا ہوں۔\n11۔ اور اب میں دنیا میں نہیں ہوں، بلکہ یہ دنیا میں ہیں، اور میں تیرے پاس آتا ہوں۔ پاک باپ، اپنے نام کے ذریعے ان سب کو برقرار رکھ جنہیں تو نے مجھے دیا ہے، تاکہ وہ ایک ہو جائیں، جیسے ہم ہیں۔\n12۔ جب میں دنیا میں ان کے ساتھ تھا، تو میں نے انہیں تیرے نام پر رکھا: جو کچھ تو نے مجھے دیا وہ میں نے سنبھالا، اور ان میں سے کوئی نہیں کھویا گیا، سوائے تباہی کے بیٹے کے؛ تاکہ کتاب مقدس پوری ہو سکے۔\n13۔ اور اب میں تمہارے پاس آتا ہوں؛ اور یہ باتیں میں دنیا میں کہتا ہوں، تاکہ وہ میری خوشی خود پوری کر سکیں۔\n14۔ میں نے انہیں تمہارا وعدہ دیا ہے؛ اور دنیا نے ان سے نفرت کی ہے، کیونکہ وہ دنیا کے نہیں ہیں، جیسے میں دنیا کا نہیں ہوں۔\n15۔ میں دعا نہیں کرتا کہ تم انہیں دنیا سے نکال دو، بلکہ یہ چاہتا ہوں کہ تم انہیں برائی سے بچاؤ۔\n16. وہ دنیا کے نہیں ہیں، جیسے میں دنیا کا نہیں ہوں۔\n17۔ انہیں اپنی سچائی سے پاک کرو: تیرا کلام سچائی ہے۔\n18۔ جیسے تو نے مجھے دنیا میں بھیجا، ویسے ہی میں نے انہیں بھی بھیجا۔\n19۔ اور ان کے لیے میں خود کو مقدس بناتا ہوں، تاکہ وہ بھی سچائی کے ذریعے پاک ہوں۔ {مقدس...: یا، واقعی مقدس}\n20۔ میں صرف ان کے لیے دعا نہیں کرتا، بلکہ ان کے لیے بھی دعا کرتا ہوں جو اپنے کلام کے ذریعے مجھ پر ایمان لائیں گے؛\n21. تاکہ وہ سب ایک ہوں؛ جیسے تو، اے باپ، مجھ میں ہے، اور میں تجھے میں، تاکہ وہ بھی ہم میں ایک ہو جائیں: تاکہ دنیا یقین کرے کہ تو نے مجھے بھیجا ہے۔\n22۔ اور جو جلال تو نے مجھے دیا وہ میں نے انہیں دیا؛ تاکہ وہ ایک ہوں، جیسے ہم ایک ہیں:\n23. میں ان میں ہوں، اور تم میرے میں، تاکہ وہ ایک میں کامل ہو جائیں؛ اور تاکہ دنیا جان لے کہ تم نے مجھے بھیجا ہے، اور ان سے محبت کی ہے، جیسے تم نے مجھ سے محبت کی۔\n24. اے باپ، میں چاہتا ہوں کہ وہ بھی، جنہیں تو نے مجھے دیا ہے، میرے ساتھ ہوں جہاں میں ہوں؛ تاکہ وہ میری شان کو دیکھ سکیں، جو تم نے مجھے دی ہے: کیونکہ تم نے مجھے دنیا کی بنیاد سے پہلے ہی محبت کی۔\n25۔ اے راستباز باپ، دنیا نے تمہیں نہیں جانا: لیکن میں نے تمہیں جانا ہے، اور وہ جانتے ہیں کہ تو نے مجھے بھیجا ہے۔\n26۔ اور میں نے ان کے سامنے تمہارا نام اعلان کیا ہے، اور اعلان کروں گا: کہ جس محبت سے تم نے مجھ سے محبت کی وہ ان میں ہو، اور میں ان میں۔","1۔ جب یسوع نے یہ الفاظ کہے، تو وہ اپنے شاگردوں کے ساتھ سیڈرون نامی ندی کے پار نکلے، جہاں ایک باغ تھا، جس میں وہ داخل ہوئے اور اپنے شاگردوں کے ساتھ۔\n2۔ اور یہودا، جس نے اسے دھوکہ دیا، اس جگہ کو جانتا تھا: کیونکہ یسوع اکثر اپنے شاگردوں کے ساتھ وہاں جاتا تھا۔\n3۔ یھودا، جب اسے سردار کاہنوں اور فریسیوں کی طرف سے ایک گروہ اور افسران ملے، تو وہ لالٹینوں، مشعلیں اور ہتھیار لے کر وہاں آیا۔\n4۔ یسوع، جو کچھ بھی اس پر آنا تھا، جانتے ہوئے آگے بڑھا اور ان سے کہا، تم کس کی تلاش میں ہو؟\n5۔ انہوں نے اسے جواب دیا، یسوع ناصری کو۔ یسوع نے انہیں کہا، میں ہوں {وہ}۔ اور یہودا بھی، جس نے اسے دھوکہ دیا، ان کے ساتھ کھڑا رہا۔\n6۔ جیسے ہی اس نے ان سے کہا، میں {وہ} ہوں، وہ پیچھے ہٹے اور زمین پر گر گئے۔\n7۔ پھر اس نے دوبارہ ان سے پوچھا، تم کس کو تلاش کرتے ہو؟ اور انہوں نے کہا، ناصری کے یسوع۔\n8۔ یسوع نے جواب دیا، میں نے تمہیں بتایا ہے کہ میں {وہ} ہوں: اگر تم مجھے تلاش کرتے ہو تو ان کے راستے جانے دو:\n9۔ تاکہ وہ کہاوت پوری ہو جائے، جو اس نے کہا، جن میں سے تم نے مجھے دیے، میں نے کچھ نہیں کھویا۔\n10۔ پھر شمعون پطرس نے تلوار نکالی، اور اعلیٰ پادری کے خادم کو مارا اور اس کا دایاں کان کاٹ دیا۔ خادم کا نام مالکس تھا۔\n11۔ پھر یسوع نے پطرس سے کہا، اپنی تلوار غلاف میں رکھو: وہ پیالہ جو میرے باپ نے مجھے دیا ہے، کیا میں اسے نہیں پیتا؟\n12۔ پھر یہودیوں کے گروہ، کپتان اور افسران نے یسوع کو پکڑ کر باندھ دیا،\n13۔ اور اسے پہلے اناس کے پاس لے گئی؛ کیونکہ وہ قیافا کے سسر تھے، جو اسی سال اعلیٰ کاہن تھے۔ {سال: سال۔ اور عناس نے مسیح کو قیافا اعلیٰ کاہن کے پاس باندھ کر بھیجا}\n14۔ اب وہ قیافہ تھا، جس نے یہودیوں کو نصیحت دی کہ ایک آدمی کو قوم کے لیے قربان کرنا مناسب ہے۔\n15۔ اور شمعون پطرس یسوع کے پیچھے گیا، اور {اسی طرح} ایک اور شاگرد: وہ شاگرد اعلیٰ کاهن کو معلوم تھا، اور وہ یسوع کے ساتھ اعلیٰ کاهن کے محل میں داخل ہوا۔\n16۔ لیکن پیٹر دروازے کے پاس کھڑا تھا۔ پھر وہ دوسرا شاگرد باہر آیا، جسے اعلیٰ پادری جانتا تھا، اور اس نے دروازہ رکھنے والی سے بات کی اور پطرس کو اندر لایا۔\n17۔ تو وہ لڑکی جو پیٹر کے دروازے کی حفاظت کرتی تھی، کہتی ہے، کیا تم بھی اس آدمی کی شاگردوں میں سے نہیں ہو؟ وہ کہتا ہے، میں نہیں ہوں۔\n18۔ اور خادم اور افسران وہاں کھڑے تھے، جنہوں نے کوئلے کی آگ جلائی تھی؛ کیونکہ سردی تھی: اور انہوں نے خود کو گرم کیا: اور پیٹر ان کے ساتھ کھڑا ہو کر خود کو گرم کیا۔\n19۔ پھر اعلیٰ کاہن نے یسوع سے اپنے شاگردوں اور اس کے عقیدے کے بارے میں پوچھا۔\n20۔ یسوع نے جواب دیا، میں نے دنیا سے کھل کر بات کی؛ میں نے کبھی عبادت گاہ اور مندر میں تعلیم دی، جہاں یہودی ہمیشہ رجوع کرتے ہیں؛ اور میں نے خفیہ طور پر کچھ نہیں کہا۔\n21. تم مجھ سے کیوں پوچھ رہے ہو؟ ان سے پوچھو جنہوں نے مجھے سنا، میں نے ان سے کیا کہا: دیکھو، وہ جانتے ہیں میں نے کیا کہا۔\n22۔ اور جب اس نے یہ کہا، تو ایک افسر جو کھڑا تھا اس نے یسوع کو ہاتھ کی ہتھیلی سے مارا اور کہا، کیا تم اعلیٰ پادری کو ایسا جواب دیتے ہو؟ {کے ساتھ...: یا، ایک چھڑی کے ساتھ}\n23۔ یسوع نے جواب دیا، اگر میں نے برائی کی ہے تو برائی کی گواہی دو: لیکن اگر ٹھیک ہے تو مجھے کیوں مسکرا رہے ہو؟\n24۔ اب انناس نے اسے قیافہ، اعلیٰ کاہن کے پاس باندھ کر بھیج دیا تھا۔\n25۔ اور شمعون پیٹر کھڑا ہوا اور خود کو گرم کیا۔ لہٰذا انہوں نے اس سے کہا، کیا تم بھی اس کے شاگردوں میں سے نہیں ہو؟ اس نے انکار کیا اور کہا، میں نہیں ہوں۔\n26۔ اعلیٰ پجاری کے خادموں میں سے ایک، جو اس کا رشتہ دار ہے، جس کا کان پیٹر نے کاٹ دیا تھا، کہتا ہے، کیا میں نے تمہیں باغ میں اس کے ساتھ نہیں دیکھا؟\n27۔ پیٹر نے پھر انکار کیا: اور فورا مرغ کا عملہ۔\n28۔ پھر انہوں نے یسوع کو قیافا سے ہال آف جسٹس تک لے جایا: اور وقت بہت جلدی تھا؛ اور وہ خود عدالت کے ہال میں نہیں گئے، کہیں ان کی بے حرمتی نہ ہو جائے؛ بلکہ کہ وہ فسح کھا سکتے ہیں۔ {ہال...: یا، پیلاطس کا گھر}\n29۔ پیلاطس پھر ان کے پاس گیا اور کہا، تم اس آدمی کے خلاف کیا الزام لگا رہے ہو؟\n30۔ انہوں نے جواب دیا اور کہا، اگر وہ بدکار نہ ہوتا تو ہم اسے تمہارے حوالے نہ کرتے۔\n31۔ پھر پیلاطس نے ان سے کہا، اسے لے لو اور اپنے قانون کے مطابق اس کا فیصلہ کرو۔ یوں یہودیوں نے اس سے کہا، ہمارے لیے کسی کو قتل کرنا جائز نہیں:\n32. تاکہ یسوع کا وہ کلام پورا ہو جائے، جو اس نے کہا، جس سے ظاہر ہوتا ہے کہ اسے کون سی موت مرنی چاہیے۔\n33۔ پھر پیلاطس دوبارہ عدالتی ہال میں داخل ہوا، یسوع کو بلایا اور اس سے کہا، کیا تم یہودیوں کے بادشاہ ہو؟\n34۔ یسوع نے جواب دیا، کیا تم یہ بات اپنے بارے میں کہہ رہے ہو، یا دوسروں نے تمہیں میرے بارے میں بتایا؟\n35۔ پیلاطس نے جواب دیا، کیا میں یہودی ہوں؟ تمہاری اپنی قوم اور سردار کاہنوں نے تمہیں میرے حوالے کر دیا ہے: تم نے کیا کیا؟\n36۔ یسوع نے جواب دیا، میری بادشاہی اس دنیا کی نہیں: اگر میری بادشاہی اسی دنیا کی ہوتی تو میرے خادم لڑتے، کہ مجھے یہودیوں کے حوالے نہ کیا جاتا: لیکن اب میری بادشاہی یہاں سے نہیں ہے۔\n37۔ اس لیے پیلاطس نے اس سے کہا، کیا تم بادشاہ ہو؟ یسوع نے جواب دیا، تو کہتی ہو کہ میں بادشاہ ہوں۔ اسی مقصد کے لیے میں پیدا ہوا، اور اسی مقصد کے لیے میں دنیا میں آیا، تاکہ میں سچائی کی گواہی دوں۔ جو بھی سچ ہے وہ میری آواز سنتا ہے۔\n38۔ پیلاطس اس سے کہتا ہے، سچائی کیا ہے؟ اور جب اس نے یہ کہا، تو وہ دوبارہ یہودیوں کے پاس گیا اور انہیں کہا، میں اس میں کوئی قصور نہیں پاتا۔\n39۔ لیکن آپ کی ایک روایت ہے کہ میں آپ کو پاس اوور پر ایک چھوڑ دوں: تو کیا آپ چاہیں گے کہ میں آپ کو یہودیوں کے بادشاہ کو آزاد کروں؟\n40۔ پھر سب دوبارہ رونے لگے، کہنے لگے، یہ آدمی نہیں، بلکہ باراباس۔ اب باراباس ایک ڈاکو تھا۔","1۔ پھر پیلاطس نے یسوع کو لے لیا اور اسے کوڑے مارے۔\n2۔ اور سپاہیوں نے کانٹوں کا تاج بچھایا اور اس کے سر پر رکھا، اور اس پر جامنی چادر پہنائی،\n3۔ اور کہا، سلام، یہودیوں کے بادشاہ! اور انہوں نے اپنے ہاتھوں سے اسے مارا۔\n4۔ لہٰذا پیلاطس دوبارہ باہر آیا اور ان سے کہا، دیکھو، میں اسے تمہارے پاس لے آیا ہوں تاکہ تم جان لو کہ میں اس میں کوئی عیب نہیں پاتا۔\n5۔ پھر یسوع سامنے آیا، کانٹوں کا تاج اور جامنی لباس پہنے ہوئے۔ اور {پیلاطس} ان سے کہتا ہے، دیکھو یہ آدمی!\n6۔ جب سردار کاہنوں اور افسران نے اسے دیکھا، تو انہوں نے پکارا، \"اسے مصلوب کرو، اسے صلیب پر چڑھاؤ۔\" پیلاطس ان سے کہتا ہے، اسے لے لو اور مصلوب کر دو، کیونکہ میں اس میں کوئی عیب نہیں پاتا۔\n7۔ یہودیوں نے جواب دیا، ہمارے پاس قانون ہے، اور ہمارے قانون کے مطابق اسے مرنا چاہیے، کیونکہ اس نے خود کو خدا کا بیٹا بنایا۔\n8۔ جب پیلاطس نے یہ کہاوت سنی تو وہ زیادہ خوفزدہ ہو گیا؛\n9۔ اور پھر سے عدالت گاہ میں گیا، اور یسوع سے کہا، تم کہاں سے آئے ہو؟ لیکن یسوع نے اسے کوئی جواب نہیں دیا۔\n10۔ پھر پیلاطس اس سے کہتا ہے، کیا تم مجھ سے بات نہیں کرتے؟ کیا تم نہیں جانتے کہ میرے پاس تمہیں مصلوب کرنے اور تمہیں آزاد کرنے کی طاقت ہے؟\n11۔ یسوع نے جواب دیا، \"تم میرے خلاف کوئی طاقت نہیں رکھ سکتے جب تک کہ یہ تمہیں اوپر سے نہ دیا جائے: اس لیے جس نے مجھے تمہارے حوالے کیا اس کا گناہ بڑا ہے۔\n12۔ اور اس کے بعد پیلاطس نے اسے رہا کرنے کی کوشش کی، لیکن یہودیوں نے پکارا، کہ، اگر تم اس آدمی کو جانے دو گے تو تم قیصر کے دوست نہیں ہوگے، جو خود کو بادشاہ بنائے گا وہ قیصر کے خلاف بولے گا۔\n13۔ جب پیلاطس نے یہ کہاوت سنی، تو اس نے یسوع کو سامنے لایا اور عدالت کی نشست پر بیٹھ گیا، جسے فرش کہا جاتا ہے، لیکن عبرانی زبان میں گباتھا۔\n14۔ اور یہ فسح کی تیاری تھی، اور تقریبا چھٹے گھنٹے کے قریب: اور وہ یہودیوں سے کہتا ہے، دیکھو تمہارا بادشاہ!\n15۔ لیکن انہوں نے پکارا، {اسے} کو دور کرو، {اسے} کو دور کرو، اسے مصلوب کرو۔ پیلاطس ان سے کہتا ہے، کیا میں تمہارے بادشاہ کو مصلوب کر دوں؟ سردار پادریوں نے جواب دیا، ہمارے پاس قیصر کے سوا کوئی بادشاہ نہیں۔\n16۔ پھر اس نے اسے ان کے حوالے کیا تاکہ اسے صلیب پر چڑھایا جائے۔ اور انہوں نے یسوع کو لے لیا، اور {اسے} کو لے گئے۔\n17۔ اور وہ اپنی صلیب اٹھائے ایک جگہ میں گیا جسے {کھوپڑی کی جگہ} کہا جاتا ہے، جسے عبرانی میں گولگوتا کہا جاتا ہے:\n18۔ جہاں انہیں صلیب پر چڑھایا گیا، اور دو اور اس کے ساتھ، دونوں طرف، ایک اور یسوع کو درمیان میں۔\n19۔ اور پیلاطس نے ایک عنوان لکھا، اور {اسے} صلیب پر لکھا۔ اور تحریر تھی، یسوع ناصرت، یہودیوں کا بادشاہ۔\n20۔ اس عنوان میں بہت سے یہودیوں کا ذکر تھا: کیونکہ جہاں یسوع کو مصلوب کیا گیا تھا وہ شہر کے قریب تھی: اور یہ عبرانی، {اور} یونانی، {اور} لاطینی میں لکھا گیا تھا۔\n21۔ پھر یہودیوں کے سردار کاہنوں نے کہا کہ پیلاطس کو پلائٹس، یہودیوں کا بادشاہ نہ لکھو؛ لیکن اس نے کہا، میں یہودیوں کا بادشاہ ہوں۔\n22۔ پیلاطس نے جواب دیا، جو میں نے لکھا ہے، میں نے لکھا ہے۔\n23۔ پھر سپاہیوں نے جب یسوع کو صلیب پر چڑھایا تو اس کے کپڑے اتارے اور ہر سپاہی کے لیے چار حصے بنائے۔ اور ساتھ ہی {اس کا} کوٹ: اب کوٹ بغیر سلائی کے تھا، اوپر سے پورے اوپر بنا ہوا تھا۔ {بنا ہوا: یا، بنایا گیا}\n24۔ لہٰذا انہوں نے آپس میں کہا، آؤ اسے نہ پھاڑیں، بلکہ اس کے لیے قرعہ اندازی کریں، جس کا وہ ہوگا: تاکہ کتاب مقدس پوری ہو جائے، جس میں لکھا ہے، انہوں نے میرا لباس ان کے درمیان بانٹ دیا، اور میرے لباس کے لیے قرعہ ڈالا۔ لہٰذا یہ سب سپاہیوں نے کیا۔\n25۔ اب وہاں یسوع کی صلیب کے پاس کھڑی تھی، اس کی ماں اور اس کی ماں کی بہن، کلیوفاس کی {بیوی} مریم، اور مریم مگدلینہ۔ {کلیوفاس: یا، کلوپاس}\n26۔ جب یسوع نے اپنی ماں اور شاگرد کو کھڑا دیکھا، جس سے وہ محبت کرتا تھا، تو اس نے اپنی ماں سے کہا، عورت، دیکھو اپنے بیٹے!\n27۔ پھر وہ شاگرد سے کہتا ہے، دیکھو تمہاری ماں! اور اسی وقت سے وہ شاگرد اسے اپنے {گھر} لے گیا۔\n28۔ اس کے بعد، یسوع جانتے ہوئے کہ اب سب کچھ مکمل ہو چکا ہے، تاکہ کتاب مقدس پوری ہو سکے، کہتے ہیں، میں پیاس رکھتا ہوں۔\n29۔ اب ایک برتن سرکہ سے بھرا ہوا رکھا گیا: اور انہوں نے ایک سپنج کو سرکہ سے بھر دیا، اور اسے ہیسوپ پر رکھا، اور اسے اس کے منہ میں رکھا۔\n30۔ جب یسوع نے سرکہ وصول کیا، تو اس نے کہا، یہ ختم ہو گیا: اور اس نے اپنا سر جھکا لیا اور بھوت کو چھوڑ دیا۔\n31۔ یہودیوں، چونکہ یہ تیاری تھی، کہ لاشیں ہفتہ کے دن صلیب پر نہ رہیں (کیونکہ وہ سبت کا دن بڑا دن تھا)، انہوں نے پیلاطس سے درخواست کی کہ ان کی ٹانگیں ٹوٹ جائیں اور انہیں لے جایا جائے۔\n32۔ پھر سپاہیوں نے آئے، اور پہلے کے پیر توڑ دیے، اور دوسرے کے بھی جو اس کے ساتھ مصلوب کیا گیا تھا۔\n33۔ لیکن جب وہ یسوع کے پاس آئے اور دیکھا کہ وہ پہلے ہی مر چکا ہے، تو انہوں نے اس کی ٹانگیں نہیں توڑیں:\n34۔ لیکن ایک سپاہی نے نیزہ لے کر اس کے پہلو میں گھونپ دیا، اور فورا خون اور پانی سے باہر آیا۔\n35۔ اور جس نے دیکھا اس کا ریکارڈ خالی ہے، اور اس کا ریکارڈ سچ ہے، اور وہ جانتا ہے کہ وہ سچ کہتا ہے تاکہ تم ایمان لاؤ۔\n36۔ کیونکہ یہ کام کیے گئے تاکہ کتاب مقدس پوری ہو، اس کی ہڈی نہیں ٹوٹے گی۔\n37۔ اور ایک اور آیت میں کہا گیا ہے، وہ اس کو دیکھیں گے جسے انہوں نے چھید دیا۔\n38۔ اور اس کے بعد یوسف آف اریمتھیا نے، جو یسوع کا شاگرد تھا، لیکن یہودیوں سے خوف کی وجہ سے خفیہ طور پر اس نے پیلاطس سے درخواست کی کہ وہ یسوع کا جسم لے جائے: اور پیلاطس نے اجازت دی۔ لہٰذا وہ آیا اور یسوع کے جسم کو لے لیا۔\n39۔ اور نیکودیمس بھی آیا، جو سب سے پہلے رات کو یسوع کے پاس آیا، اور مر اور ایلو کا مرکب لایا، تقریبا سو پاؤنڈ وزن۔\n40۔ پھر انہوں نے یسوع کے جسم کو لے کر مصالحوں کے ساتھ لینن کے کپڑوں میں لپیٹ دیا، جیسا کہ یہودیوں کا دفن کرنے کا طریقہ ہے۔\n41۔ اب جہاں اسے مصلوب کیا گیا تھا، وہاں ایک باغ تھا؛ اور باغ میں ایک نیا مقبرہ، جس میں ابھی تک انسان نہیں رکھا گیا تھا۔\n42۔ یسوع وہاں لٹکے، یہودیوں کی تیاری {دن} کی وجہ سے؛ کیونکہ قبر قریب تھی۔","1۔ ہفتے کا پہلا {دن} مریم مگدلینی صبح سویرے آتی ہے، جب ابھی اندھیرا تھا، مقبرے کی طرف جاتی ہے، اور قبر سے ہٹایا گیا پتھر آتا ہے۔\n2۔ پھر وہ دوڑتی ہے، اور شمعون پطرس اور دوسرے شاگرد کے پاس آتی ہے، جس سے یسوع محبت کرتا تھا، اور ان سے کہتی ہے: انہوں نے خداوند کو قبر سے نکال لیا ہے، اور ہمیں معلوم نہیں کہ انہوں نے اسے کہاں رکھا ہے۔\n3۔ پطرس اور وہ دوسرا شاگرد باہر نکلے اور قبر پر آئے۔\n4۔ تو وہ دونوں ایک ساتھ دوڑے: اور دوسرا شاگرد پیٹر سے پہلے بھاگ گیا، اور قبر تک پہنچا۔\n5۔ اور وہ جھک گیا، {اور اندر دیکھا}، لینن کے کپڑے پڑے ہوئے دیکھے؛ پھر بھی وہ اندر نہیں گیا۔\n6۔ پھر شمعون پطرس اس کے پیچھے آتا ہے، اور قبر میں جاتا ہے، اور کپڑوں کو دیکھتا ہے،\n7۔ اور نیپکن، جو اس کے سر کے گرد تھا، لینن کے کپڑوں کے ساتھ نہیں پڑا تھا، بلکہ ایک جگہ پر لپٹا ہوا تھا۔\n8۔ پھر وہ دوسرا شاگرد بھی اندر گیا، جو پہلے قبر پر آیا، اور اس نے دیکھا اور ایمان لایا۔\n9۔ کیونکہ ابھی تک وہ صحیفہ نہیں جانتے تھے کہ اسے مردوں میں سے دوبارہ زندہ ہونا چاہیے۔\n10۔ پھر شاگرد دوبارہ اپنے گھر چلے گئے۔\n11۔ لیکن مریم قبر کے پاس بغیر کھڑی روتی رہی: اور روتے ہوئے جھک گئی، {اور قبر میں دیکھا}،\n12۔ اور دو سفید لباس میں دو فرشتے بیٹھے ہوئے دیکھتا ہے، ایک سر پر اور دوسرا پیروں میں، جہاں یسوع کا جسم پڑا تھا۔\n13۔ اور وہ اس سے کہتے ہیں، عورت، تم کیوں روتی ہو؟ وہ ان سے کہتی ہے، کیونکہ انہوں نے میرے رب کو لے لیا ہے، اور مجھے نہیں معلوم کہ انہوں نے اسے کہاں رکھا ہے۔\n14۔ اور جب اس نے یہ کہا، تو اس نے پیچھے مڑ کر یسوع کو کھڑا دیکھا، اور اسے معلوم نہ ہوا کہ وہ یسوع ہے۔\n15۔ یسوع نے اس سے کہا، عورت، کیوں رو رہی ہو؟ تم کس کی تلاش میں ہو؟ وہ، اسے مالی سمجھتے ہوئے، اس سے کہتی ہے، جناب، اگر آپ اسے یہاں سے لے آئے ہیں تو مجھے بتائیں کہ آپ نے اسے کہاں رکھا ہے، میں اسے لے جاؤں گی۔\n16۔ یسوع نے اس سے کہا، مریم۔ اس نے خود کو موڑ کر کہا، ربونی؛ یعنی، ماسٹر۔\n17۔ یسوع نے اس سے کہا، مجھے چھوؤ مت؛ کیونکہ میں ابھی اپنے باپ کے پاس نہیں پہنچا: لیکن میرے بھائیوں کے پاس جاؤ اور انہیں کہو، میں اپنے باپ اور تمہارے باپ کے پاس چڑھتا ہوں؛ اور میرے خدا اور تمہارے خدا کے لیے۔\n18۔ مریم مگدلین آئی اور شاگردوں کو بتایا کہ اس نے خداوند کو دیکھا ہے، اور {کہ} اس نے یہ باتیں اس سے کہی ہیں۔\n19۔ پھر اسی دن شام کو، جو ہفتے کا پہلا دن تھا، جب دروازے بند کیے گئے جہاں شاگرد یہودیوں سے ڈر کر جمع تھے، یسوع آیا اور درمیان میں کھڑا ہوا اور ان سے فرمایا، تم پر امن ہو۔\n20۔ اور جب اس نے یہ کہا، تو اس نے ان کے سامنے اپنے ہاتھ اور پہلو دکھائے۔ پھر شاگرد خوش ہوئے جب انہوں نے خداوند کو دیکھا۔\n21۔ پھر یسوع نے ان سے دوبارہ کہا، تم پر امن ہو: جیسے {میرا} باپ نے مجھے بھیجا ہے، اسی طرح میں تمہیں بھیجتا ہوں۔\n22۔ اور جب اس نے یہ کہا، تو اس نے ان پر سانس پھولی اور ان سے کہا، روح القدس کو قبول کرو:\n23۔ جن کے گناہ تم معاف کرتے ہو، وہ ان پر معاف کر دیے جاتے ہیں؛ {اور} جن کے {گناہ} تم اپنے پاس رکھتے ہو، وہ محفوظ رہتے ہیں۔\n24۔ لیکن توماس، بارہ میں سے ایک، جسے دیدیمس کہا جاتا تھا، ان کے ساتھ نہیں تھا جب یسوع آیا۔\n25۔ دوسرے شاگردوں نے اس سے کہا، ہم نے خداوند کو دیکھا ہے۔ لیکن اس نے ان سے کہا، جب تک میں اس کے ہاتھوں میں ناخنوں کا نشان نہ دیکھوں، اور اپنی انگلی ناخنوں کے نشان میں نہ ڈالوں، اور اپنا ہاتھ اس کے پہلو میں دھکیل دوں، میں یقین نہیں کروں گا۔\n26۔ اور آٹھ دن بعد اس کے شاگرد اندر آئے، اور تھامس ان کے ساتھ: {تب} یسوع آیا، دروازے بند ہو گئے، اور درمیان میں کھڑے ہو کر کہا، تم پر سلامتی ہو۔\n27۔ پھر وہ تھامس سے کہتا ہے، اپنی انگلی یہاں تک پہنچو، اور میرے ہاتھوں کو دیکھو؛ اور اپنا ہاتھ یہاں بڑھاؤ، اور اسے میرے پہلو میں دھکیل دو: اور بے وفا نہ ہو، بلکہ ایمان لاؤ۔\n28۔ اور تھامس نے جواب دیا اور کہا، میرے رب اور میرے خدا۔\n29۔ یسوع نے اسے کہا، تھامس، کیونکہ تو نے مجھے دیکھا، تو نے ایمان لایا: مبارک ہیں وہ جو نہیں دیکھ سکے، اور پھر بھی ایمان لائے ہیں۔\n30۔ اور یسوع نے اپنے شاگردوں کی موجودگی میں واقعی بہت سے دوسرے نشانات دیے، جو اس کتاب میں نہیں لکھے گئے:\n31۔ لیکن یہ تحریریں اس لیے لکھی گئی ہیں کہ آپ یقین کر سکیں کہ یسوع مسیح ہے، خدا کا بیٹا؛ اور یہ یقین رکھتے ہوئے کہ تم اس کے نام سے زندگی حاصل کر سکتے ہو۔","1۔ ان سب کے بعد یسوع نے دوبارہ خود کو طبریہ کے سمندر پر شاگردوں کے سامنے ظاہر کیا؛ اور اسی حکمت سے اس نے خود کو دکھایا۔\n2۔ وہاں شمعون پطرس اور تھامس جنہیں دیدیمس کہا جاتا ہے، اور ناتھنائل آف قانا گلیل میں، اور زبدی کے {بیٹے} اور اس کے دو دیگر شاگرد بھی تھے۔\n3۔ شمعون پیٹر ان سے کہتا ہے، میں مچھلی پکڑنے جا رہا ہوں۔ وہ اس سے کہتے ہیں، ہم بھی تمہارے ساتھ چلتے ہیں۔ وہ آگے بڑھے اور فورا ایک جہاز میں سوار ہو گئے؛ اور اس رات انہوں نے کچھ نہیں پکڑا۔\n4۔ لیکن جب صبح ہوئی تو یسوع کنارے پر کھڑے تھے: لیکن شاگردوں کو معلوم نہیں تھا کہ وہ یسوع ہیں۔\n5۔ پھر یسوع نے ان سے کہا، بچوں، کیا آپ کے پاس کوئی گوشت ہے؟ انہوں نے جواب دیا، نہیں۔ {بچے: یا، سرز}\n6۔ اور اس نے ان سے کہا، جہاز کے دائیں طرف جال ڈال دو، اور تم ڈھونڈ لو گے۔ انہوں نے اس لیے پھینکا، اور اب وہ اسے مچھلیوں کی کثرت کے لیے کھینچنے کے قابل نہیں تھے۔\n7۔ لہٰذا وہ شاگرد جس سے یسوع محبت کرتا تھا، پطرس سے کہتا ہے، یہ خداوند ہے۔ جب شمعون پطرس نے سنا کہ یہ خداوند ہے، تو اس نے اپنا مچھلی پکڑنے والا کوٹ اس کے سامنے پہنا، (کیونکہ وہ ننگا تھا)، اور خود کو سمندر میں پھینک دیا۔\n8۔ اور دوسرے شاگرد ایک چھوٹے جہاز میں آئے؛ (کیونکہ وہ زمین سے زیادہ دور نہیں تھے، لیکن چونکہ وہ دو سو کیوبٹ تھے،) جال کو مچھلیوں سے گھسیٹتے ہوئے۔\n9۔ جیسے ہی وہ زمین پر پہنچے، انہوں نے وہاں کوئلے کی آگ دیکھی، مچھلی اور روٹی دیکھی۔\n10۔ یسوع نے ان سے کہا، جو مچھلی تم نے اب پکڑ لی ہے اسے لے آؤ۔\n11۔ شمعون پطرس اوپر گیا، اور جال کو زمین پر کھینچا، جہاں بڑی مچھلیاں تھیں، ایک سو پچاس اور تین: اور اگرچہ بہت زیادہ تھیں، پھر بھی جال نہیں ٹوٹا۔\n12۔ یسوع نے ان سے کہا، آؤ {اور} کھانا کھاؤ۔ اور کسی شاگرد نے اس سے پوچھنے کی جرات نہیں کی، تم کون ہو؟ جانتے ہوئے کہ یہ خداوند ہے۔\n13۔ پھر یسوع آتا ہے، روٹی لیتا ہے، انہیں دیتا ہے، اور مچھلی بھی دیتا ہے۔\n14۔ یہ تیسری بار ہے کہ یسوع نے اپنے شاگردوں کو خود کو دکھایا، اس کے بعد وہ مردوں میں سے زندہ ہوئے۔\n15۔ تو جب وہ کھانا کھا چکے ہیں، یسوع نے شمعون پطرس سے کہا، شمعون {یونس کا بیٹا}، کیا تم مجھ سے ان سے زیادہ محبت کرتے ہو؟ وہ اسے کہتا ہے، ہاں، خداوند؛ تم جانتے ہو کہ میں تم سے محبت کرتا ہوں۔ وہ اس سے کہتا ہے، میرے بھیڑوں کو کھلاؤ۔\n16۔ وہ دوسری بار اس سے کہتا ہے، شمعون کے بیٹے، کیا تم مجھ سے محبت کرتے ہو؟ وہ اسے کہتا ہے، ہاں، خداوند؛ تم جانتے ہو کہ میں تم سے محبت کرتا ہوں۔ وہ اس سے کہتا ہے، میری بھیڑوں کو کھلاؤ۔\n17۔ وہ تیسری بار اس سے کہتا ہے، شمعون، یوناس کے بیٹے، کیا تم مجھ سے محبت کرتے ہو؟ پیٹر غمگین تھا کیونکہ اس نے تیسری بار کہا، کیا تم مجھ سے محبت کرتے ہو؟ اور اس نے اس سے کہا، اے خداوند، تو سب کچھ جانتا ہے؛ تم جانتے ہو کہ میں تم سے محبت کرتا ہوں۔ یسوع نے اسے کہا، میری بھیڑوں کو کھلاؤ۔\n18۔ واقعی، واقعی، میں تم سے کہتا ہوں، جب تم جوان تھے، تم نے خود کو تیار کیا اور جہاں چاہو چلے، لیکن جب تم بوڑھے ہو جاؤ گے، تو اپنے ہاتھ پھیلاؤ گے، اور کوئی اور تمہیں سنبھالے گا، اور تمہیں وہاں لے جائے گا جہاں تم نہیں چاہتے۔\n19۔ اس نے کہا، اس بات کی علامت کہ کس موت سے خدا کی جلال دینی چاہیے۔ اور جب اس نے یہ کہا، تو اس نے کہا، میرے پیچھے آؤ۔\n20۔ پھر پطرس، پلٹتے ہوئے، وہ شاگرد جو یسوع سے محبت کرتا ہے، اس کے پیچھے چلتا ہے؛ جو بھی کھانے کے وقت اپنے سینے پر ٹیک لگا کر بولا، اے خداوند، وہ کون ہے جو تمہیں دھوکہ دیتا ہے؟\n21۔ پطرس نے اسے دیکھ کر یسوع سے کہا، اے خداوند، اور یہ آدمی کیا کرے گا؟\n22۔ یسوع نے اسے کہا، اگر میں چاہوں کہ وہ میرے آنے تک رکے، تو یہ تمہارے لیے کیا ہے؟ میرے پیچھے آؤ۔\n23۔ پھر بھائیوں میں یہ کہاوت سنائی دی، کہ وہ شاگرد نہیں مرے گا: پھر بھی یسوع نے اسے نہیں کہا، وہ نہیں مرے گا؛ لیکن، اگر میں چاہوں کہ وہ میرے آنے تک رکے، تو یہ تمہارے لیے کیا ہے؟\n24۔ یہ وہ شاگرد ہے جو ان باتوں کی گواہی دیتا ہے اور یہ باتیں لکھتا ہے: اور ہم جانتے ہیں کہ اس کی گواہی سچ ہے۔\n25۔ اور یسوع نے بہت سی اور بھی چیزیں کیں، جو اگر ہر ایک کو لکھا جانا چاہیے تو شاید دنیا خود بھی وہ کتابیں نہیں رکھ سکتی جو لکھی جانی چاہئیں۔ آمین۔"];
